            migrationBuilder.InsertData(
                table: "Products",
                columns: new[] { "Id", "Author", "CategoryId", "CreatedAt", "Description", "ImageUrl", "Isbn", "Name", "Pages", "Price", "PublishDate", "Size", "Stock", "TopRated" },
                values: new object[,]
                {
                    { 313, "چورچ ر.ر مارتن", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الرواية اللي أسرت قلوب ملايين حول العالم، بترجمة منقَّحة وغلاف جديد كليًّا!\n\n�في «صِدام الملوك»، يواصل چورچ ر. ر. مارتن نسج خيوط ملحمته العظيمة «أغنيَّة الجليد والنَّار».\nبعد موت الملك روبرت باراثيون واللورد إدارد ستارك، تغرق الممالك السَّبع في فوضى عارمة، ويرفع خمسة ملوك راياتهم في صراع لا يرحم على العرش الحديدي، لتبدأ موجة جديدة من الحروب، والتحالفات الغادرة، والعهود التي تُكسر كما تُسفك الدماء.\nفي أراضي النهر والغرب، يخوض روب ستارك معركة تلو معركة للانتقام لأبيه وتأمين مملكته الجديدة.\nوفي العاصمة، يجد تيريُن لانيستر نفسه وسط شبكة معقدة من المؤامرات فيما تستعد المدينة لهجوم ستانِس باراثيون، وتعيش سانزا في قلعة يزداد خطرها يومًا بعد يوم.\nووراء الجدار، يواجه چون سنو تحديات تهدِّد كل ما يعرفه عن الولاء والواجب.\nوفي الشرق في قارَّة أخرى، تواصل دنيرس تارجاريَن رحلتها بين مدن بعيدة، بحثًا عن القوة التى تمكِّنها من استعادة عرش أبيها الضائع.\nومع تصاعد النزاعات، يبدأ صدام هائل سيُعيد رسم خريطة القوة، ويُثبت أن في هذه اللعبة لا مكان للضعفاء، فإمَّا النصر وإمَّا السقوط.", "/images/products/9789778202946.webp", "9789778202946", "صدام الملوك (الجزء الثاني من اغنية الجليد والنار) سوفت كڤر (العالمي)", 1314, 1020m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 314, "چورچ ر.ر مارتن", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ما زالت حرب الملوك الخمسة مشتعلةً، تعاني ويلاتها جميع أنحاء الممالك السبع إلا قليلًا. على العرش الحديدي يجلس الملك الصبي الغاشم جوفري، فيما يسعى جدّه اللورد تايوين لانستر، يدُ الملك، لتأمين حكمه، ومن ثم تأمين السلطة لعائلة لانستر، مخططًا للقضاء على الملك ستانيس باراثيون الذي خرج مدحورًا من معركة الماء الأسود، وعلى الذئب الصغير روب ستارك الذي يقود حملةً في غرب البلاد رغم أنه فقد وطنه في الشمال.\n\nوفي تلك الأثناء تشقّ الملكة المنفية دينيرس تارجاريَن طريقها في قارّةٍ أخرى تُغرقها الدماء، بغية تحرير مئات الآلاف من العبيد والحصول على جيشٍ تستعيد به مملكتها، ومعها التنانين الثلاثة الحيّة الوحيدة في العالم.\n\nوفي الشمال يتحرّك جيشٌ جرّار من الهمج استعدادًا للهجوم على الجدار وغزو الممالك السبع، جيشٌ انضمّ إليه رجل حرس الليل جون سنو جاسوسًا، ولو أنّ شيئًا أسوأ منه يتقدّم من أقصى الشمال، العدوّ الحقيقي الذي ينشغل عنه الجميع تقريبًا بقتالهم، وقد لا تقدر جيوش الأرض كلّها على ردعه.", "/images/products/9789778203165.webp", "9789778203165", "عاصفة السيوف اغنية الجليد والنار : سوفت كڤر نسخة الشرق الأوسط", 1534, 1250m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 315, "ريبيكاياروس", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في عالم تسيطر عليه التنانين، لا مكان للضعفاء.\nڤيوليت سورينجيل لم يكن مقدّرًا لها أن تصبح فارسة، فضعف جسدها يجعلها فريسة سهلة في أكاديمية باسجياث القاسية، حيث يتدرّب النخبة على ترويض التنانين وخوض الحروب.\n\nلكن حين تُجبر على دخول الأكاديمية، تجد نفسها وسط صراعٍ مميت، حيث لا ينجو سوى الأقوى، والتنانين لا ترحم من يتعثّر.\nومع كل خطوة، تتشابك الخيانات، وتنكشف أسرار قد تهدم المملكة بأكملها.\n\nفهل ستنجح ڤيوليت في البقاء حيّة… أم تكون مجرد رماد على جناح رابع؟", "/images/products/9789778202991.webp", "9789778202991", "الجناح الرابع نسخه (السوفت كڤر)", 818, 900m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 316, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بعد سلسلة من الفقد والصدمات، تجاهد ليك للتأقلم مع حياتها الجديدة، متحملة مسؤولية شقيقها كيل بعد وفاة والديها.\nفي الوقت ذاته يواجه ويل نفس التحدي، إذ يرعى شقيقه الأصغر كولدر ويسعى للحفاظ على علاقته بليك. لكن ضغوط الحياة لا ترحم، الغيرة والشكوك، وظهور أشخاص جدد يختبرون قوة هذا الحب، أمور تدفع العلاقة إلى حافة الانهيار.\nوحين تتعرض ليك لمحنة تهدد حياتها، يكتشف كلاهما أن الحب ليس مجرد مشاعر جميلة، بل التزام يومي وتضحية، وصبر إزاء كل ما تكشفه الحياة من وجوه قاسية.", "/images/products/9789778202861.webp", "9789778202861", "مرحلة الإنسحاب", 304, 375m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 317, "مارك هادون", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "(كريستوفر) فتى ذكي يتسم بالتوحّد، يعثر على كلب الجيران (ولنجتون) مقتولًا بطريقة غامضة في حديقة السيدة (شيرز).\nتسيء الشرطة فهم تصرفاته فيجد نفسه متهمًا دون قصد، فيقرر أن يبدأ تحقيقه الخاص مثل أبطال روايات الجريمة التي يعشقها.\nلكن ما يبدأ كلغز بسيط، يتحول تدريجيًا إلى رحلة تكشف أسرارًا كبيرة عن عائلته، وأكاذيب لم يكن يتخيل وجودها.\nوبين والده الذي يحاول حمايته - على طريقته - ووالدته التي تتكشَّف له حقيقتها فجأة، يضطر (كريستوفر) إلى مواجهة عالم مربك، مليء بالفوضى والضوضاء.", "/images/products/9789778202922.webp", "9789778202922", "حادثة كلب منتصف الليل المثيرة", 338, 375m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 318, "م.د-سبنسر", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رحلة عائلية إلى الريف، وطفلان مشاكسان لا ينفكَّان عن مضايقة بعضهما بعضًا، وأب وأم يحاولان السيطرة على كلِّ شيء.\nتبدو البداية مُملّة بعض الشيء… أليس كذلك؟\nلكن انتظر قليلًا، حتى تبدأ يدٌ خفيَّة بمطاردتهم بحبَّات التفَّاح، قبل أن يسمعوا بأسطورة الطفلين العالقين في معصرة التفَّاح، ويُحاصرهم سياجٌ خفيّ، ويكتشفون أن هناك حظيرةً مسكونة، وتظهر كؤوس الدماء!\nوفجأة… سيدرك دانيال وسارة أن هناك أبوابًا إذا فُتحت لن تُغلق بسهولة!\nفهل سيجرؤان على فتح أبواب بستان التفَّاح المخيف؟", "/images/products/9789778203028.webp", "9789778203028", "بستان التفاح المخيف (سلسلة رجفه الخوف)", 154, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 319, "م.د-سبنسر", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عندما تتحوَّل الأُمنيات إلى فخ!\nيُعاني تيمي من التنمُّر والمُضايقات التي لا تتوقَّف، حتى يمَلَّ ويُقرِّر أن يضع حدًا للأمر. وهكذا تقوده قدماه إلى كوخ العرَّافة في الكرنفال، وهناك.. يطلب أمنية واحدة فقط:أن يُصبِح أقوى من الجميع!\nوتتحقَّق الأمنية، لكنها تأتي بثمنٍ باهظ؛ انتصارات خاطِفة، وصداقات تتصدَّع، وحوادث لا تفسير لها.وهنا يسأل تيمي نفسه سؤالًا مهمًّا: هل تكفي القوَّة للتغلُّب على الخوف؟ أم أن الشجاعة الحقيقيَّة تبدأ حين تُحاول التراجُع قبل فوات الأوان؟", "/images/products/9789778203035.webp", "9789778203035", "التعويذة الغامضة (سلسلة رجفه الخوف )", 154, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 320, "م.د-سبنسر", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حين تتحوَّل الإجازة إلى لعنة!\nعندما يذهب بطل روايتنا لقضاء إجازة ريفيّة مع ابن عمّه، تبدأ الحكاية بمقالب ثقيلة وخدع لا تنتهي، قبل أن تُغيِّر لعبة كمبيوتر غامضة تُدعى «قتلة الحيوانات» كلَّ شيء.\nومن تلك اللحظة ينقلب الريف الهادئ، وتثور الحيوانات على البشر، وتتجمع ليلًا كأنها تحيك خططًا للانقلاب عليهم.\nويزداد التوتر حين يرى بطلنا ما لا يراه الآخرون، ويكتشف أن مصدر الفوضى ليس في حظيرة الحيوانات، بل في أمرٍ آخر لم يخطر على بال أحد!\nويقع الأمر كلّه على عاتقه… لمواجهة ثورة الحيوانات!", "/images/products/9789778202885.webp", "9789778202885", "ثورة الحيوانات (سلسلة رجفه الخوف)", 136, 150m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 321, "خولة حمدي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رحلة مثيرة تبدأ على متن يخت يملكه رجل لا يرحم يُدعى مايك راسل، حيث يُحتجز أسرى من جزيرة غامضة.\nوسط الضباب والعتمة، يقرر آدم، الغريب القادم من وراء البحار، أن يخاطر بكل شيء لتحريرهم، بمساعدة الطفلة الجريئة ريحان.\nلكن الهروب ليس سوى البداية...\nفالصراع يشتعل بين المحتلّ الطامع في السيطرة وحماة الجزيرة الصامدين، فيما يواصل آدم محاولة التّحكم في قدراته، وتقبّل الدّور المحوريّ الذي بات عليه تحمّله لمواجهة الخطر القادم\nفي الجهة الأخرى تعمل مانويلا، ابنة مايك، على خططها الخاصة بمساعدة من العالِمة كلاوديا، حيث يتشابك السّبق العلمي بلعبة المصالح الخبيثة\nومع تصاعد الأحداث، يقف الجميع على حافة مواجهة حاسمة، حيث لا أحد يعرف من سيبقى، ومن ستجرفه رياح الإعصار..", "/images/products/9789778203004.webp", "9789778203004", "إعصار بلا قرار", 504, 420m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 322, "خولة حمدي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "A thrilling journey begins aboard a yacht owned by a ruthless man named Mike Russell, where captives from a mysterious island are being held.\nAmid the fog and darkness, Adam — a stranger from across the seas — decides to risk everything to set them free, aided by the bold young girl, Rayhan.\nBut escape is only the beginning...\nConflict soon erupts between the greedy invader seeking domination and the steadfast guardians of the island, while Adam struggles to master his powers and accept the pivotal role he must play in facing the looming threat.\n\nMeanwhile, Manuela, Mike’s daughter, pursues her own agenda with the help of scientist Claudia, where scientific breakthroughs intertwine with a dangerous game of hidden interests.\nAs events escalate, all find themselves standing at the brink of a decisive confrontation, where no one knows who will survive, and who will be swept away by the storm", "/images/products/9789778203011.webp", "9789778203011", "A storm with no rest", 566, 420m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 323, "السعيد أبو علي", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "Jerusalem is not merely a city—it is a confluence of spiritual, national, and cultural dimensions, interwoven with historical and existential significance. It is not merely a holy city revered through the ages but a divine and universal message, a living testament to history that reaches into the depths of time. Jerusalem is inseparable from Palestine—its land, its people, and its enduring Arab identity.", "/images/products/9789978203059.webp", "9789978203059", "jerusalem epitles", 580, 600m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 324, "خولة حمدي", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عندما يستيقظ آدم في جزيرة لا تظهر على أي خريطة، مغطاة بسماء لا ترى فيها الشمس، يجد نفسه في قلب لغز قديم وقوة خارقة تختبر أصله ومصيره.\nبين شعب غامض، وحجر يشفي ويدمر، وصراع لا مهرب منه—يكتشف أن ماضي والده مرتبط بمستقبل الجزيرة... وببقائه حيًّا.", "/images/products/9789778202670.webp", "9789778202670", "سماء بلا ضياء", 496, 420m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 325, "خولة حمدي", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تُروى قصة شاب تونسي يُدعى مالك، الذي نشأ على التقاليد الإسلامية، ثم اعتُقل.\nاتخذ قرار السفر، ونسيان آلام الاحتجاز، فهاجر بطريقة غير شرعية ليبدأ رحلة جديدة ملؤها النضال، نضال مختلف؛ صراع فكري بين ما عرفه طوال حياته والثقافة السائدة، حتى وجد نفسه على حافة الإلحاد قبل أن يكتشف الطريق الصحيح.", "/images/products/9789778200645.webp", "9789778200645", "أرني أنظر إليك", 430, 300m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 326, "سانتياجو آلبارِث", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "خرج هابيل لانوثا من مركز الأمراض النفسية وهو يأمل أن يستعيد حياته السابقة مع زوجته وابنه وأصدقاءه، لكنه يجد خاله قد توفي وترك له ميراث عبارة عن بيت وأرض في قرية مويردِألماس.. وهي قرية معزولة عن العالم لها قواعدها الخاصة والتي فرضتها عائلة أوسِّت. يقرر هابيل لعيش هناك لفترة هو وعائلته في محاولة منه للتعافي وتذكر الماضي الذي كان بالنسبة له لغز كبير. لكن تحدث الكثير من المشكلات وتتكشف العديد من المفاجآت.", "/images/products/9789778202724.webp", "9789778202724", "مويرد ألماس", 414, 390m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 327, "جورج ر . ر مارتن", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«مارتن حكَّاء بالفطرة وخياله واحد في المليون. المسلسل المأخوذ عن سلسلته رائع، لكن الكُتب أفضل كثيرًا». – ستيڤن كينج\n\n«نجحت سلسلة مارتن الخيالية في إشعال خيال الملايين للسَّبب نفسه الذي جعل أعمال هوميروس وسفوكوليس وشيكسپير تدوم عصورًا». – الجارديان\n\n«مارتن الأفضل على الإطلاق بين من يكتبون في مجال الفانتازيا الملحميَّة في العصر الحالي، ولا مبالغة في وصفه بأنه تولكين الأمريكي». – تايم\n\n«موهبة مارتن في الحكي تكاد تكون خارقةً للطَّبيعة». – نيويورك تايمز\n\nفي «لُعبة العروش» يبدأ چورچ ر. ر. مارتن ملحمته الكُبرى «أغنيَّة الجليد والنَّار»، صانعًا تُحفةً أصيلةً تحوي أفضل ما في أدب الفانتازيا من تشويقٍ وغموض ومغامرة على مستوًى يتجاوز الواقع إلى رحاب الخيال الخصب، ومع ذلك لا يقلُّ واقعيَّةً عن أيٍّ من القصص الإنسانيَّة الأخرى، وهو ما أوقعَ ملايين من عُشَّاق الفانتازيا حول العالم في غرام كتابته.\nفي عالمٍ يدوم فيه الصَّيف أعوامًا والشِّتاء عُمرًا بأكمله، تبدأ سُلطة الملك الحاكم في الجنوب تتداعى بعد الظروف الغامضة المحيطة بموت يده اليُمنى الذي خدمه طويلًا بإخلاص، فلا يجد خيارًا إلَّا اللُّجوء إلى أوفى أصدقائه وآخرهم ليعاونه على حُكم البلاد، ويُقرِّر الصَّديق القبول ليَعثُر على حقيقة موت الرَّجل الذي كان بمثابة أبٍ لهما. وفيما تهبُّ الرِّياح الباردة من الشَّمال منذرةً بعودة خطرٍ قديم يُهدِّد بهلاك العالم كلِّه، تدور في قلعة الحُكم عجلة المؤامرات والمكايد بين الحُلفاء والأعداء، ويبدأ صراعٌ جديد على العرش الحديدي. لكن في لُعبة العروش لا تُوجَد منطقةٌ وُسطى، فإمَّا أن تفوز وإمَّا أن تموت.", "/images/products/9789778202557.webp", "9789778202557", "لعبة العروش - أغنية الجليد والنار (النسخة العالمية)", 1208, 990m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 328, "جورج ر.ر مارتن", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الكتب مبيعًا بحسب نيويورك تايمز • تدور أحداثه قبل قرن تقريبًا من أحداث \"لعبة العروش\"، حيث يجمع \"فارس الممالك السبع\" أول ثلاث روايات قصيرة رسمية مسبقة لعمل جورج ر. ر. مارتن الدائم \"أغنية الجليد والنار\".\n\nوقد تم تسميته كأحد أفضل الكتب لهذا العام من قبل \"لوس أنجلوس تايمز\" و\"باز فيد\".\n\nتروي هذه المغامرات، التي لم تُجمّع من قبل، عصرًا كان فيه خط تارغارين لا يزال يعتلي العرش الحديدي، ولم تزل ذاكرة آخر تنين حيّة في الوعي. قبل تيريون لانيستر وبودريك بين، كان هناك دانك وإيگ. فارس شاب ساذج لكنه شجاع في نهاية المطاف، سير دانكن الطويل يتفوق على خصومه من حيث القامة إن لم يكن الخبرة. يرافقه رفيقه الصغير، ولد يُدعى إيگ—الاسم الحقيقي له مخفي عن كل من يصادفانه. ورغم أن أبطالاً أكثر غرابة قد لا نجدهم في جميع أنحاء ويستروس، فإن مصائر عظيمة تنتظر هذين الاثنين، إلى جانب أعداء أقوياء ومكائد ملكية ومغامرات فذة.\n\nوبفضل أكثر من 160 رسماً جديداً من إبداع جاري جياني، يُعدّ \"فارس الممالك السبع\" مجموعة لا غنى عنها تثبت أن الفروسية لم تمت بعد—على الأقل ليس بعد.\n\nالقراء الذين يعشقون مارتن وقدرته على استخراج الدراما الإنسانية الحسية من أي قصة، سيسرون برؤية هذه الثلاثية مجمعة ومعززة بحياة إضافية.» — Booklist\n«السبب الحقيقي لاستكشاف هذه المجموعة هو أنها ببساطة سرد رائع؛ يصنع مارتن عالمًا حيًا ونابضًا بطريقة لا يستطيعها سوى عدد قليل من الكتاب... [رسومات جياني] تُحيي أحداث الروايات القصيرة بأسلوب بديع.» — Tech Times\n«مثير... كما لدى تولكين ملحمته \"السيلمارليون\"، فإن [جورج ر. ر.مارتن]  يمتلك هذه الثلاثية من القصص التأسيسية؛ فهي تنجح بمفردها، وبالإضافة إلى ذلك، تجعل المعجبين يتوقون للمزيد.» — Kirkus Reviews\n«مغامرة فانتازيا خالصة، مع اثنين من أكثر الشخصيات الرئيسية التي أحبها مارتن على الإطلاق.» — Bustle\n«قراءة لا غنى عنها لعشاق مارتن... مقدمة مثيرة لسلسلة \"أغنية الجليد والنار\" الأكثر مبيعًا، غنية بالدراما الإنسانية وبناء العالم الملون الذي يميز باقي كتب السلسلة.» — Publishers Weekly", "/images/products/9789778202441.webp", "9789778202441", "فارس من الممالك السبع", 536, 450m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 329, "چورچ ر.ر مارتن", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بكل النيران والغضب الذي تعود عليه الجماهير من الكاتب الدولي الأكثر مبيعًا، جورج ر. ر. مارتن، يأتي هذا المجلد الأول من التاريخي القطعي ذو الجزأين لعائلة تارجارين في ويستروس.\n\nقبل قرون من أحداث \"لعبة العروش\"، استقر بيت تارجارين—العائلة الوحيدة من أمراء التنانين التي نجت من كارثة فاليريا—في \"دراجونستون\". تبدأ \"النار والدم\" قصتهم مع الأسطورة أيغون الفاتح، مبتكر العرش الحديدي، وتتابع سرد أجيال تارجارين الذين قاتلوا للحفاظ على هذا المقعد الأيقوني، وصولًا إلى الحرب الأهلية التي كادت أن تمزق سلالتهم.\n\nما الذي حدث حقًا خلال \"رقصة التنانين\"؟ ولماذا أصبحت زيارة فاليريا مميتة بعد الكارثة؟ وما أصل بيض التنانين الثلاثة لدى دانيريس؟ هذه بعض الأسئلة التي يُجيب عليها هذا السجل الحيوي، كما يرويها معلم حكيم من \"السيتاديل\"، ويضم أكثر من ثمانين رسماً بالأبيض والأسود من إبداع الفنان دوج ويتلي. لقد أطلّع القراء على لمحات من هذا السرد في مجلدات مثل \"عالم الجليد والنار\"، لكن الآن، ولأول مرة، يُكشف النقاب عن النسيج الكامل لتاريخي تارجارين.\n\nبكل عظمة وشمولية \"تاريخي انهيار وسقوط الإمبراطورية الرومانية\" لجِبون، يُعدّ \"النار والدم\" اللعبة النهائية للعروش، مانحًا القراء تقديرًا جديدًا للتاريخي الديناميكي، غالبًا داميًا ودائم الإثارة لويستروس.", "/images/products/9789778201321.webp", "9789778201321", "النار والدم (مجلدين)", 968, 890m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 330, "روبرت چوردان", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكاتبة الحائزة على لقب نيويورك تايمز الأفضل مبيعًا، والتي أبهرت القرّاء بروايتها ميؤوس منه، قصة ما\nحدث عندما التقت الفتاة المضطربة سكاي مع صديق طفولتها الذي فقدته منذ زمن طويل، دين هولدر.\nبمساعدة دين هولدر، كشفت سكاي عن أسرار عائلية صادمة وتصالحت مع ذكريات وعواطف خلّفت\nجروحًا عميقة.\nميئوس منه كانت قصة سكاي. والآن، في رواية فقدان الأمل، نتعرف أخيرًا على حقيقة &quot;دين هولدر&quot;.\nيعيش هولدر حياة مظلمة بسبب الطفلة الصغيرة التي لم يتمكن من إنقاذها من الخطر الوشيك، وتغمره\nمشاعر الذنب والندم. لم يتوقف هولدر عن البحث عنها، يعتقد أن العثور عليها سيجلب له السلام الذي\nيحتاجه للتقدّم في الحياة. ومع ذلك، لم يكن هولدر يتوقع أن يواجه المزيد من الألم في لحظة لقائهما مجددًا.\nفي رواية فقدان الأمل يكشف هولدر طريقة تأثير أحداث طفولة &quot;سكاي&quot; عليه وعلى عائلته، مما دفعه إلى\nالبحث عن الفداء من خلال إنقاذها. ولكنه فقط حب سكاي الذي يمكنه من البدء في شفاء نفسه.", "/images/products/9789778202564.webp", "9789778202564", "عجله الزمن-الصيد العظيم", 994, 875m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 331, "روبرت چوردان", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور عجلة الزمن وتأتي الأعمار وتذهب، تاركةً وراءها ذكريات تتحول إلى أسطورة. تتلاشى الأسطورة لتصبح خرافة، وحتى الخرافة تُنسى عندما يعود العصر الذي أنبتها. ما كان، وما سيكون، وما هو عليه الآن، قد يقع جميعه تحت ظل الظلام.\n\nتصل مويرين دامودرِد إلى \"حقول إيموند\" في مهمة للعثور على المنبأ عنه الذي سيقف ضد \"الظلام المطلق\"، ذلك الكيان الخبيث الذي يزرع بذور الفوضى والدمار. وعندما يغزو فريق شرير من نصف بشر ونصف وحوش القرية باحثين عن عدو سيدهم، تقنع مويرين راند آل ثور وأصدقائه بترك ديارهم والدخول إلى عالم أكبر لا يُتصوَّر، مليء بالمخاطر التي تكمن في الظلال والنور.", "/images/products/9789778201604.webp", "9789778201604", "عجلة الزمن - عين العالم (مجلدين)", 1104, 830m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 332, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من الكاتبة كولين هوفر، تأتي رواية تستكشف الحياة بعد المأساة وروح الحب الدائمة.\n\nعندما يلتقي ليدز بليلى، يقتنع بأنه سيقضي بقية حياته معها—حتى يحدث هجوم غير متوقع يترك ليلى تكافح من أجل بقائها. وبعد أسابيع من العلاج في المستشفى، تتعافى ليلى جسديًا، لكن الندوب العاطفية والعقلية قد غيَّرت المرأة التي أحبها ليدز. ومن أجل إعادة علاقتهما إلى مسارها الصحيح، يأخذ ليدز ليلى إلى النزل الذي التقيا فيه لأول مرة. وما إن يصلان، حتى يأخذ سلوك ليلى منعطفًا غريبًا، وهذا مجرد واحد من العديد من الأحداث الغامضة.\n\nشعر ليدز بأن ليلى باتت بعيدة عنه، فوجد العزاء في \"ويلو\"—ضيف آخر في النزل يتشاركان الهموم. ومع ازدياد فضوله تجاه \"ويلو\"، يضعه رغبته في مساعدتها على إيجاد إجابات في مواجهة مباشرة مع رفاهية ليلى. وسرعان ما يدرك ليدز أنه عليه أن يختار بينهما، إذ لا يستطيع مساعدة كلاهما، وإن اتخذ قرارًا خاطئًا، فقد يكون ذلك مدمّرًا للجميع.", "/images/products/9789778201635.webp", "9789778201635", "ليلى (النسخة العالمية)", 400, 390m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 333, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في بعض الأحيان، يكون من تحبك هو من يؤذيك أكثر.\n\nلم تكن حياة ليلي مفروشة بالورود دومًا، لكن ذلك لم يمنعها يومًا من الكفاح من أجل الحياة التي تطمح إليها. لقد قطعت شوطًا طويلًا منذ بلدة صغيرة في مين حيث نشأت؛ فقد تخرجت من الجامعة، وانتقلت إلى بوسطن، وأسست مشروعها الخاص. وعندما تشعر بشرارة مع جراح أعصاب وسيم يُدعى رايل كينكيد، يبدو كل شيء في حياتها وكأنه خير يفوق الخيال.\n\nرايل شخص حازم وعنيد وربما متعجرف بعض الشيء، لكنه أيضًا حساس وعبقري ولديه ميول حنونة تجاه ليلي؛ وطريقته في الزي الطبي تزيده جاذبية. لا تستطيع ليلي إخراجه من أفكارها، لكن نفوره المطلق للعلاقات يثير قلقها. وبينما تجد نفسها استثناءً من قاعدته الصارمة، تتساءل دومًا عما الذي جعل رايل هكذا منذ البداية.\n\nوبينما تغمرها التساؤلات حول علاقتها الجديدة، تتسلل إلى ذهنها أيضًا ذكريات أطلس كورريغان—حبها الأول وصلةً بالماضي الذي تود أن يبقى منسيًّا. كان هو روحها التوأم وحاميها، ومع ظهور أطلس فجأة، تتعرض كلُّ ما بنت ليلي مع رايل للخطر.", "/images/products/9789778202212.webp", "9789778202212", "ينتهي معنا (النسخة العالمية)", 480, 470m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 334, "كولين هوڤر", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحلم أم شابة تعاني من الاضطراب بالحصول على فرصة للتكفير عن أخطائها في هذه القصة المؤلمة المفعمة بالأمل، من تأليف كاتبة نيويورك تايمز الأكثر مبيعًا، كولين هوفر. بعد قضائها خمس سنوات في السجن نتيجة خطأ مأساوي، تعود كينا روان إلى المدينة التي ساءت فيها الأمور، على أمل أن تعيد لم شملها مع ابنتها الصغيرة البالغة من العمر أربع سنوات.\n\nلكن الجسور التي حرقتها كينا تبدو مستحيلة الإصلاح؛ فكل من له علاقة بحياة ابنتها مصمم على إغلاق الأبواب أمامها، مهما بذلت من جهد لإثبات جدارتها. والوحيد الذي لم يُغلق الباب أمامها تمامًا هو ليجر وارد، صاحب حانة محلية وواحد من الروابط القليلة المتبقية مع ابنة كينا. لكن إن اكتشف أحد كيف أصبح ليجر تدريجيًا جزءًا مهمًا من حياة كينا، فإنهما كلاهما سيخاطران بفقدان ثقة كل من يهمه أمرهما. تشكل الشخصيتان رابطًا رغم الضغوط المحيطة بهما، ومع نمو علاقتهما الرومانسية، يتزايد الخطر؛ فيجب على كينا أن تجد وسيلة لتكفير أخطاء ماضيها من أجل بناء مستقبل ينبض بالأمل والشفاء.", "/images/products/9789778201352.webp", "9789778201352", "ما يذكرني بك", 422, 385m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 335, "براندون ساندرسون", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "منذ سنوات مضت، كان لديه رفاق سلاح، وقضية يؤمِن بها، لكِن الآن، الرجُل الذي يُطلِق على نفسه اسم (نوماد)، لا يعرِف سوى حياة الهروب.\nيُجبَر (نوماد) على القفز من عالمٍ إلى آخرٍ ضمن كون (كوزمير)، وتُطارده (سرية الليل) القاسية للغاية، وتبدأ أحداث روايتنا عندما يهبط على كوكبٍ جديد، وسُرعان ما يجِد نفسه مُحاصرًا على الفور وسط صراع بين طاغية والمُتمرِّدين الذي لا يُريدون سوى الهروب من التحوُّل إلى عبيد لديه. وكُل ذلِك تحت التهديد المُستمِر لشروق الشمس الذي ستؤدي حرارته إلى إذابة الحجارة.\nلكِنه غير قادِر على فهم لُغتهم!\nهل يستطيع مواصلة الصراع، واكتساب القوّة الكافية للقفز خارِج العالم، قبل أن يدفع جسده أو عقله الثمن النهائي؟", "/images/products/9789778202496.webp", "9789778202496", "الذي اضاءه نور الشمس", 596, 750m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 336, "براندون ساندرسون", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور الرواية حول شخصيتين رئيسيتين، يومي والرسام، الذين ينحدران من عالمين\nمختلفين تمامًا، حيث يعيش الرسام في مدينة يكتنفها الظلام والكوابيس لكنها أكثر تطورًا\nمقارنةً ببلدة يومي التي تتميَّز بحدائقها ولكن أهلها يعتمدون كليًا في حياتهم على\nالأرواح. \nتتداخل حياتهما بطرقٍ غامضة عبر تبادلٍ غريبٍ للأجساد عندما ينامان. لذلك يتعيَّن على\nيومي والرسام أن يتعلَّما التكيُّف مع أدوارهما الجديدة في عوالم بعضهما البعض. وبينما\nيحاولان حل أسرار وضعهما المُلتبِس في رحلاتهما العجيبة تلك، يكتشفان الحقائق\nالمخفية حول عالميهما والقوى الشريرة التي تسيطر عليهما؛ فيشرعان معًا في مهمة\nلإنقاذ مجتمعات بعضهما بعضًا من الانزلاق إلى الهاوية. \nوكعادة روايات براندون ساندرسون ذات الطابع الخيالي في عالم كوزمير، تتناول\nالرواية موضوعات الهوية واستكشاف الذات والتحرر فضلًا عن التعاون في سبيل أداء\nالواجب.", "/images/products/9789778202519.webp", "9789778202519", "يومي ورسام الكوابيس - عالم كوزمير", 612, 790m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 337, "براندون ساندرسون", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لم تعرف تريس في جزيرتها المحاطة بمحيطٍ بلون الزمرد سوى الحياة البسيطة، حيث كانت تستمتع بتجميع الأكواب التي يجلبها البحارة من أراضٍ بعيدة والاستماع إلى قصص صديقها تشارلي.\nولكن، عندما انطلق والدها في رحلة للعثور على عروس واندلعت الكارثة، اضطرت تريس للاختباء على متن سفينة والسعي للعثور على الساحرة في بحر منتصف الليل المميت.\nوسط محيطات مليئة بالأبواغ يعج بها القراصنة، هل تستطيع تريس أن تودع حياتها البسيطة وتصنع لنفسها مكانًا في بحر قد تُميت قطرة ماء منه في لحظة؟", "/images/products/9789778201567.webp", "9789778201567", "فتاة بحر الزمرد ( هارد كڤر )", 578, 730m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 338, "براندون ساندرسون", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يستفيق رجل في فسحة مفتوحة بما يشبه إنجلترا العصور الوسطى، دون أن يتذكر من هو، أو من أين أتاه، أو لماذا وُضع في هذا المكان.\nيطارُه أعداء من زمنه، وحيد الأمل في نجاته يكمن في استرجاع ذكرياته المفقودة، وكسب حلفاء من السكان المحليين، وربما الثقة بتلك الخرافات التي يرددونها.\nوكانت مساعدته الوحيدة من \"العالم الحقيقي\" في دليل بعنوان \"دليل الساحر الاقتصادي للبقاء في إنجلترا العصور الوسطى\"، لكن نسخته انفجرت أثناء النقل. القليل من الشظايا التي نجاها تكشف له عن معالم وضعه، فهل سيتمكن من فك طلاسمها قبل فوات الأوان؟", "/images/products/9789778201628.webp", "9789778201628", "دليل الساحر المقتصد للنجاة في انجلترا في القرون الوسطى", 448, 410m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 339, "نانسي سبرينجر", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عندما تكتشف إينولا هولمز، الأخت الصغرى لشيرلوك هولمز، اختفاء والدتها في يوم عيد ميلادها الرابع عشر، تعلم أنها الوحيدة القادرة على العثور عليها.\nمتنكرةً في هيئة أرملة مفجوعة، تنطلق إينولا إلى قلب لندن لتكشف عن مصير والدتها، ولكن حتى اسم \"هولمز\" لا يمكن أن يجهزها لما ينتظرها.\nوفجأةً، تتورط في اختطاف ماركيز باسيولويذر الشاب؛ فتعلم أنها عليها الفرار من الأشرار القاتلين، وتحرير الماركيز المدلل، والأهم من ذلك، التملص من أخيها الأكبر الفطن، بينما تجمع الأدلة حول اختفاء والدتها.\nمنسوجةً بصوت وجو شوارع لندن الفيكتورية المليئة بالفئران، تقدم هذه الرواية المثيرة والذكية لعشاق الغموض أفضل ما في هذا النوع الأدبي.", "/images/products/9789778200737.webp", "9789778200737", "إينولا هولمز وقضية إختفاء الماركيز", 268, 170m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "10×17", 10, false },
                    { 340, "نانسي سبرينجر", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إذا قلبنا اسم إينولا، نحصل على \"وحيدة\"، وهي كذلك؛ وحيدة في أكبر وأظلم وأوسخ مدينة في العالم.\nإنها مطاردة من قبل أشهر محقق عالمي—أخوها شيرلوك هولمز. ومن أجل الحرية، يجب عليها التملص منه، لكن ماذا يمكنها أن تفعل لتخفيف وطأة وحدتها؟\nحينما تكتشف مخبأً سريًا لرسومات فحمية بديعة، تشعر وكأنها رفيقة الروح للفتاة التي رسمتها، لكنها تكتشف أن تلك الفتاة، السيدة الصغيرة سيسيلي، اختفت دون أثر.\nمتجاوزةً شوارع منتصف الليل التي يجوبها القتلة، يتوجب على إينولا فك رموز الأدلة—سلم مائل، وبائع عيان مخادع، وكتيبات سياسية—للعثور على السيدة اليسارية، لكنها تخاطر بكشف أسرارها أكثر مما ينبغي لإنقاذ السيدة سيسيلي من شرير عظيم.\nهل سينقلب عليها قلبها الوحيد في نهاية المطاف؟\nفي هذا الجزء الثاني من سلسلة \"أسرار إينولا هولمز\" الشهيرة، تُقدم لنا نانسي سبرينجر، الحائزة مرتين على جائزة إدغار، كلّ الدهشة والتشويق في لندن الفيكتورية، مستمرةً بمغامرات إحدى أذكى وأروع البطلات في الأدب المعاصر.", "/images/products/9789778201260.webp", "9789778201260", "إينولا هولمز وقضية السيدة العسراء", 206, 160m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "10×17", 10, false },
                    { 341, "ريتشل رينية", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", "/images/products/9789778201437.webp", "9789778201437", "مذكرات حمقاء \" حكايات فتاة ليست سعيدة جدًا \"", 338, 300m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 342, "ريتشل رينية", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", "/images/products/9789778201444.webp", "9789778201444", "مذكرات حمقاء \" فتاة حفل ليست مشهورة جدًا \"", 288, 300m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 343, "ريتشل رينية", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", "/images/products/9789778201420.webp", "9789778201420", "مذكرات حمقاء \" نجمة بوب ليست مشهورة جدًا \"", 320, 300m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 344, "ريتشل رينية", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", "/images/products/9789778201468.webp", "9789778201468", "مذكرات حمقاء - أميرة تزلج ليست رشيقة جدًا", 358, 300m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 345, "ريتشل رينية", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", "/images/products/9789778201451.webp", "9789778201451", "مذكرات حمقاء - فتاة تعرف كل شئ ليست ذكية جدا", 332, 300m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 346, "ريتشل رينية", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "إنها نسخة من \"Diaries of a wimpy kid\" للفتيات في هذه الرواية الفكاهية!\n\nوصفة الكارثة: 4 حفلات؛ أضف صديقتين وفتاة تُعجبك؛ اقسم على فتاة شريرة عازمة على تدمير نيكي؛ امزج جيدًا، وضع أصابعك على عينيك، واستعد للشعور بالإحراج الشديد.\nكنت أظن أن هذا لن يحدث أبدًا، لكن حياتي بدأت أخيرًا تسير في طريق النجاح.\nأنا أتكيف مع مدرستي الجديدة وأقضي وقتي مع أفضل صديقاتي، كلوي وزوي. وتخيلوا! فقد طلب مني معجبِي، براندون، أن أكون شريكته في المختبر—خطوة رائعة حقًا.\nلكن، عندما أسمع فتاة شريرة تُدعى ماكنزي تتفاخر بأن براندون سيأخذها إلى رقصة الهالوين، يغمرني شعور بالحزن الشديد، فيتوجب عليّ التسجيل لقضاء الهالوين في حفلة أطفال مع أختي الصغيرة المشاكسة، بريانا.\nلحسن حظي، اكتشفت أن ماكنزي تكذب، وقد يتحقق حلمي بالذهاب إلى الحفلة مع براندون! لكن، هل أستطيع التوفيق بين حدثين في نفس الوقت والبقاء سالمة وسط سلسلة من المحن والتجارب والكوارث؟! النجدة!!!", "/images/products/9789778201413.webp", "9789778201413", "مذكرات حمقاء - محطمة قلوب ليست سعيدة جدا", 352, 300m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 347, "ماريسا ماير", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يكتظ شوارع بكين الجديدة الصاخبة بالبشر والآليون معًا، فيما ينهب طاعون قاتل السكان. ومن الفضاء، يراقب شعب قمري لا يرحم، منتظرًا اللحظة المناسبة لشن هجومه. لا أحد يدرك أن مصير الأرض يعتمد على فتاة واحدة…\n\"سيندر\" الميكانيكية الموهوبة، وهي سيبورغ، تحمل بين جنباتها لعنةً وهبةً في آنٍ واحد.\nفهي مواطنة من الدرجة الثانية ذات ماضٍ غامض، محتقرة من قِبل زوجة أبيها وملومة على مرض أختها غير الشقيقة. ولكن عندما تتشابك حياتها مع حياة الأمير الوسيم \"كاي\"، تجد نفسها فجأةً في قلب صراع بين المجرات، وتبدأ قصة جذب محرّم. عالقة بين الواجب والحرية، وبين الولاء والخيانة، عليها أن تكشف أسرار ماضيها لحماية مستقبل عالمها.", "/images/products/9789778200904.webp", "9789778200904", "سلسة سجلات القمر - سندر", 424, 370m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 348, "ماريسا ماير", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "عادَت سيندر وتحاول الفرار من السجن، رغم أنها ستصبح المطلوبة رقم واحد في الكومنولث إذا نجحت في ذلك، وذلك في الجزء الثاني من سلسلة ماريسا ماير.\nفي مكان بعيد عن هنا، تختفي جدة \"سكارليت بينوِت\"، ويتضح أن هناك الكثير من الأمور التي لا تعرفها سكارليت عن جدتها أو عن الخطر الداهم الذي رافقها طوال حياتها. حينما تصادف سكارليت \"وولف\"، المقاتل في الشوارع الذي قد يحمل معلومات عن مكان جدتها، تتردد في الثقة بهذا الغريب، لكنها تجد نفسها مشدودة نحوه، وهو بدوره يشعر بانجذاب نحوها. وبينما يكشف كل من سكارليت ووولف لغزًا، يلتقيان بسيندر، فيجد الجميع أنفسهم مضطرين للبقاء خطوةً أمام الملكة القمرية الشرسة \"ليفانا\".\nتستمر المغامرة في إعادة سرد قصة خيالية جديدة تجمع بين عناصر سندريلا وذات الرداء الأحمر.", "/images/products/9789778201241.webp", "9789778201241", "سلسة سجلات القمر - سكارليت", 480, 400m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 349, "ماريسا ماير", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "حتى في المستقبل.. ثمة فتيات في محنة!\nبعدما خاطرت كريس بكل شيء لتحذير سندر من الخطة الشريرة للملكة لافانا، تواجه مشكلة طفيفة؛ حيث لبثت سجينة على متن قمر صناعي منذ طفولتها، لا تحظى برفقة عدا الشاشات الشبكية؛ كل هذا الوقت أمام الشاشة جعل من كريس قرصانة بارعة، ولسوء الحظ فقد تلقت لتوها أوامر من لافانا بتعقب سندر وشريكها الوسيم! وحين تخفق مجازفة إنقاذ كريس من قِبل سِندر وكابتن ثورن وسكارليت ووولف؛ تفترق المجموعة وتلوذ كريس أخيرًا بالفرار، إنما للحرية مقابل باهظ الثمن! في هذه الأثناء، لن تدع الملكة لافانا شيئًا يمنع زواجها من الإمبراطور كاي.\nربما لم تتطوع كريس وسكارليت وسندر لإنقاذ العالم، لكن عساهن أمله الوحيد!", "/images/products/9789778202502.webp", "9789778202502", "سلسلة سجلات القمر - كريس", 592, 480m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 350, "چيف ليندسي", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هو وحش ساحر... بطل مُظلم... قاتل متسلسل يقتل السيئين فقط.\nيعاني ديكستر مورغان من ضغوط هائلة؛ فليس من السهل أن تكون قاتلًا متسلسلاً أخلاقيًا، خاصةً أثناء محاولته تجنب الشكوك التي لا تهتز من قبل الرقيب الخطير \"دوكس\" الذي يعتقد أن ديكستر مختل عقليًا... وهو بالطبع كذلك.\nفي محاولة لإبعاد دوكس عن أثره، اضطر ديكستر للغوص عميقًا في زيه المموه المحكم. وبينما لا يعمل كمحلل لبقع الدم في شرطة ميامي، يقضي معظم وقته مع صديقته المشرقة \"ريتا\" وطفليها، يحتسي بيرة خفيفة ويصبح ببطء أول \"مدمن قطنية\" في العالم.\nلكن إلى متى يستطيع ديكستر أن يلعب لعبة \"ركل العلبة\" بدلًا من \"تقطيع القاتل\"؟ إلى متى ستجبره \"الراكب المظلم\" بداخل نفسه على إسقاط التمثيل وإطلاق وحشه الداخلي؟\nفي أوقات الشدائد، تطرق الفرص الباب؛ إذ يظهر مهووس شرير بشكل خاص يشق طريقه عبر ميامي بأسلوب ملتوي يترك ديكستر عاجزًا عن الكلام. ومع اشتعال شهوته المظلمة من جديد، تنجذب أخته \"ديبورا\" (المحققة الجديدة الشرسة في ميامي) إلى القضية، فيتضح سريعًا أن الإمساك بوحش يتطلب وحشًا آخر—ولكن لن يتمكن ديكستر من الاستغراق في البحث عن هدف جديد حتى تُختطف عدوه اللدود، ما لم يُفاجئه هدفه أولاً…\nبذكاءٍ لا يُضاهى وبطابع جديد أضاف إليه \"جيف ليندسي\" تألقًا مبهرًا، يأخذ ديكستر مورغان إلى مستوى جديد من الجاذبية المُظلمة، مقدّمًا لنا أحد أكثر السرديين ابتكارًا وتلوّنًا منذ سنوات.", "/images/products/9789778201277.webp", "9789778201277", "دكستر - المتفاني بإخلاص", 360, 290m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 351, "بوب براير", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نظرة جديدة كبرى على كنوز وأسرار قبر توت عنخ آمون في الذكرى المئوية لاكتشافه.\nغالبًا ما يُعتقد أن قصة توت عنخ آمون انتهت حينما نُقلت آلاف القطع التي اكتشفها هوارد كارتر ولورد كارنايفون إلى المتحف المصري في القاهرة وعُرضت. لكن هناك المزيد في قصة توت عنخ آمون.\nفي \"توت عنخ آمون والقبر الذي غيّر العالم\" نتابع مائة عام من البحوث التي جرت منذ اكتشاف القبر: نتعلم أن العديد من القطع في القبر صُنعت من حديد نيزكي جاء من الفضاء الخارجي؛ وتظهر أدلة جديدة أن توت عنخ آمون ربما كان محاربًا دخل ساحة المعركة؛ ويأخذنا المؤلف \"بوب برايَر\" خلف كواليس عمليات الفحص بالأشعة المقطعية لمومياواته لكشف أسرار الفرعون.\nكما يسلط الكتاب الضوء على التأثير الواسع النطاق لاكتشاف قبر توت عنخ آمون على مجالات تتجاوز علم المصريات؛ حيث يتم فحص كيف أثر اكتشاف القبر على السياسة المصرية وساهم في سقوط الاستعمار في مصر. وعلى الصعيد العالمي، بدأت المعارض الضخمة التي ترفع مبالغ هائلة للمتحفّات في جميع أنحاء العالم مع توت عنخ آمون، كما نشأت فكرة توثيق كل قطعة تُكتشف في مكانها قبل نقلها. وإلى حد كبير، ساهمت \"توت مانيا\" التي أحاطت باكتشاف القبر في تعزيز الهوس الحديث بمصر القديمة.", "/images/products/9789778201482.webp", "9789778201482", "توت عنخ آمون و المقبرة التي غيرت العالم", 448, 400m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 352, "بيترفرونسكي", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من خلال كُتب مثل (القتلة المُتسلسلين) و(القاتِلات المُتسلسِلات) و(أبناء قابيل)، رسَّخ بيتر فرونِسكي مكانته كخبيرٍ رائِد في تاريخ القتلة المُتسلسلين. في هذا السرد التاريخي، الأول والأخير، للعصر الذهبي للقتل المُتسلسِل في الولايات المُتحِدة الأمريكيَّة، حينما ارتفعَت أعداد القتلة المُتسلسلين وضحاياهُم بشكلٍ كبير، يروي فرونِسكي قصص أغرب وأبرز جرائِم القتل المُتسلسِل من الخمسينيَّات وحتى أوائِل القرن الحادي والعشرين. من تِد بندي إلى قاتِل الولاية الذهبيَّة، يزداد هوسنا بهؤلاء القتلة المُتسلسلين القدامى يومًا بعد توم. ويُقدِّم هذا الكِتاب لعُشَّاق الجرائِم الحقيقيَّة كُل ما يشتهونه، بدءً من الأسماء الشهيرة (مثل إد كِمبر وجيفري دامر)، وصولًا إلى القضايا الأقل شُهرة (مثل ميلفِن ريس وهارفي جلاتمان).", "/images/products/9789778202588.webp", "9789778202588", "القتله المتسلسلين الأمريكيين", 614, 490m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 353, "غريدي هيندريكس", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في أفلام الرعب، تكون \"الفتيات النهائيات\" هن من تبقى واقفة حين تنتهي الأشرطة. لقد نجين من أسوأ ليلة في حياتهن… لكن ماذا يحدث بعد ذلك؟\nمثل روايته الأكثر مبيعًا \"دليل نادي الكتاب الجنوبي لقتل مصاصي الدماء\"، تأتي أحدث أعمال \"جرادي هندريكس\" بإثارة سريعة، ورعب مخيف، وكوميديا سوداء ساخرة.\nمن مناشير السلسلة إلى قاتلات معسكرات الصيف، تُقدم \"مجموعة الدعم للفتيات النهائيات\" تحيةً لسلاسل الرعب الأكثر شهرة—أفلام مثل \"مجزرة منشار تكساس\"، و\"كابوس شارع إيلم\"، و\"صرخة\".\n\"لينيت تاركينغتون\" هي فتاة نهائية حقيقية نجت من مذبحة. وعلى مدار أكثر من عقد من الزمن، اجتمعت مع خمس فتيات نهائيات أخريات ومع معالجات نفسية لدعم من نجا من المستحيل، في محاولة لإعادة بناء حياتهن. ثم تفوت إحداهن اجتماعًا، وتتحقق أسوأ مخاوفهن—فشخصًا ما يعرف عن المجموعة ويصر على تمزيق حياتهن مجزأة قطعة قطعة.\nلكن سر الفتيات النهائيات هو أنه مهما كانت الظروف صعبة، مهما كان الليل مظلمًا، ومهما كانت السكاكين حادة، فلن يستسلمن أبدًا.", "/images/products/9789778201529.webp", "9789778201529", "مجموعة دعم الفتيات الناجيات من القتلة المتسلسلين", 410, 390m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 354, "أحمد خالد توفيق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذه إعادة تقديم جديدة للقصة الشهيرة \"بحّاران\"، التي كانت في الأصل المدخل الثالث والخمسين ضمن سلسلة فانتازيا للدكتور أحمد خالد توفيق. تتضمن هذه النسخة عددًا كبيرًا من التعديلات والتغييرات التي كانت كفيلة بحصولها على جائزة مصطفى عزوز للأدب الطفولي عام 2018. كما تُعدّ بداية لسلسلة جديدة غير مكتملة تشير إلى قصة أخرى عن الحريق العظيم في روما.\nيروي السرد قصة صحفي يمتلك آلة زمن على شكل كشك هاتف، تُمكّنه من السفر بحرية عبر الزمن لمشاهدة وتوثيق الأحداث التاريخية المهمة. في هذه الرواية، يروي قصة اللقاء بين أسد البحر، الإماراتي أحمد بن ماجد، والطاغية البرتغالي فاسكو دا جاما.", "/images/products/9789778200867.webp", "9789778200867", "الميرانتي أمير البحار", 128, 50m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "10×17", 10, false },
                    { 355, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تحكي الرواية قصة الدكتور محفوظ، الرجل العجوز الغريب الذي توفي فقيرًا، مخلفًا وراءه صندوقًا مليئًا بالأسرار والأشياء الغريبة في قبو منزله، يحتوي على ذكرياته ومذكراته وملاحظاته عن القصص العجيبة التي عاشها.", "/images/products/9789778200294.webp", "9789778200294", "الأن نفتح الصندوق 1", 234, 170m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 356, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نستمر في سرد قصة الدكتور محفوظ، ذلك الرجل العجوز الغريب الذي رحل فقيرًا تاركًا خلفه الصندوق ذاته المملوء بالأسرار والأشياء الغريبة، والذي يحوي ذكرياته ومذكراته وملاحظاته عن القصص العجيبة التي عاشها.", "/images/products/9789778200300.webp", "9789778200300", "الأن نفتح الصندوق 2", 196, 150m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 357, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وفي الجزء الأخير، نختتم رحلتنا مع الدكتور محفوظ، الرجل العجوز الغريب الذي توفي فقيرًا، مخلفًا خلفه ذلك الصندوق المليء بالأسرار والأشياء الغريبة في قبو منزله، الذي يحتوي على ذكرياته ومذكراته وملاحظاته عن القصص العجيبة التي عاشها.", "/images/products/9789778200317.webp", "9789778200317", "الأن نفتح الصندوق 3", 146, 130m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 358, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تبدأ الرواية بازالة القوات المصرية لأحد أبرز عملاء الموساد الإسرائيلي بنجاح. وفي الوقت نفسه، يستعد الرئيس محمد أنور السادات لإلقاء خطاب تاريخي يعلن فيه هذا الاعتقال، مؤكداً للعالم أن المصريين دائمًا ينتصرون في كل الميادين. غير أن الأحداث تأخذ منعطفًا غير متوقع، حيث تنجح المخابرات الإسرائيلية في السيطرة على إحدى الشخصيات المحورية في القيادة المصرية، اللواء رفعت.", "/images/products/9789778200751.webp", "9789778200751", "سلسلة فاي - عملية الاستاذ", 162, 140m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 359, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الرواية هي إثارة جريمة من نسج خيال الكاتب، وتدور حول عملية مُحكمة لاسترجاع فيلم مصغر من تل أبيب. يقوم بتنفيذ المهمة العميل \"فاي\" واستراتيجية فريدة من نوعها تخصه. وتملأ القصة أحداث مشوقة تجعل منها قراءة مثيرة لعشاق الروايات البوليسية، والتجسس، والأدب الاستخباراتي.", "/images/products/9789778200744.webp", "9789778200744", "سلسلة فاي - عملية تل ابيب", 224, 170m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 360, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في الكتاب الثالث من السلسلة، نتتبع الشاب المصري \"فاي\" وهو يقود عمليات حساسة وخطيرة. وبفضل مهاراته الاستثنائية وقدراته الفريدة التي تميّزه عن بقية أعضاء مديرية المخابرات العامة المصرية، يُوكل إليه العديد من المهام شبه المستحيلة، ومن بينها عملية \"النسر الوحيد\".", "/images/products/9789778200881.webp", "9789778200881", "سلسلة فاي - عملية البعث", 120, 120m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 361, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تبدأ أحداث الرواية في صحراء سيناء (1973 م / 1393 هـ)، حيث تدور كل الأحداث حول شجاعة الجندي المصري الشاب (سائقة-144) في عملية هجومية ضد الاحتلال الإسرائيلي لتحرير سيناء. وتنتهي المعركة بترك الشاب جريحًا على رمال الصحراء، إلا أنه يواصل الدفاع باسم \"مصر\" وحده.", "/images/products/9789778200874.webp", "9789778200874", "سلسلة فاي - عملية النسر المنفرد", 152, 140m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 362, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في لحظة درامية، يقول أحدهم: «سأحتاج بالتأكيد إلى شريك للمرحلة القادمة، وأنتِ يا من لا يُمكن رفضكِ». ثم رفع العقرب الذهبي أمام عينيه وتابع: «وهذا سيكون شعار المرحلة القادمة...» وتلألأت عيناه قائلاً: «العقرب».\nوفي تلك اللحظة، أعلن القدر عن ميلاد محارب جديد، مقاتل للجريمة؛ ميلادٌ تهتز من أجله قلوب أخطر المجرمين، وترتفع سيف العدالة عاليًا. إنه ميلاد \"العقرب\".", "/images/products/9789778200782.webp", "9789778200782", "سلسلة العقرب - سيف العدالة", 216, 170m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 363, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لقد صُدمت ما لا يقل عن ثلاثة أرباع مصر عندما أعلنت الأخبار في الفجر عن القبض على صالح عثمان بتهمة الخيانة. تدفّق الناس لشراء الجرائد لمعرفة المزيد من التفاصيل، وزادت دهشتهم عندما لم يجدوا أي أثر لهذه الأخبار في الجرائد، إذ أن القبض تم بعد طباعة الصحف. لم يصدق الناس آذانهم؛ فقد كان صالح عثمان من أقوى رجال البلاد على الرغم من عدم توليه أي منصب رسمي.", "/images/products/9789778200799.webp", "9789778200799", "سلسلة العقرب - ملك الجريمة", 210, 170m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 364, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "توقف هو متذكرًا أمرًا، ثم عاد إليها ووضع بطاقة العقرب على كرسيها قائلاً: «صدقيني، لقد فقدتِ اللقب إلى الأبد». وتوجه نحو الباب لينهي الحديث قائلاً: «لقب الإمبراطورة»، وأغلق الباب بهدوء خلفه.", "/images/products/9789778200812.webp", "9789778200812", "سلسلة العقرب - الامبراطورة", 148, 130m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 365, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ولم يكن الأمر سهلاً بالطبع على \"العقرب\" أن يخلع قناعه، فذلك كان يهدد حياته وعمله ومستقبله بسهولة. لكن الوضع لم يكن سهلاً أو خفيفًا؛ فقد كان يواجه عدوه اللدود الذي لا يرغب في شيء سوى كشف هويته، ولم يكن يحمل سلاحًا بينما كان خصمه يشير إليه بسلاح، مما استدعى مناورة ذكية.", "/images/products/9789778200768.webp", "9789778200768", "سلسلة العقرب مملكة الشر -العصابة", 272, 180m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 366, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "قال وهو يبتسم بمكر: «هذه المرة، لا يعمل العقرب بمفرده، بل هو في مهمة رسمية». أدركت غادة حينها أن العقرب عاد إلى عالم مكافحة الجريمة بكل قوته.", "/images/products/9789778200805.webp", "9789778200805", "سلسلة العقرب - مهمة رسمية", 130, 120m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 367, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وعند باب القبو، وبهدوء وسكينة، وقف آخر رجل لم يكن أحد يتوقعه… العقرب. لم يكن يشير بسلاح نحوهم، بل وقف هناك، معقود الذراعين أمام صدره، مستندًا إلى الباب وبابتسامة ساخرة. والأهم من ذلك، كان يرتدي القناع الأسود الشهير... قناع العقرب.", "/images/products/9789778200775.webp", "9789778200775", "سلسلة العقرب - خلف القناع", 132, 120m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 368, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتواصل أحداث هذه القصة بعملية تهدف إلى نقل وليد من إسرائيل إلى مصر. وتغوص في الألعاب العقلية والنفسية التي يمارسها القائد \"العميد\"، وخططه ضد الموساد، متفوقًا عليهم مرة أخرى بذكائه، إذ أنهم عادةً ما يلجؤون إلى العنف بدلاً من الفكر.", "/images/products/9789778201697.webp", "9789778201697", "سلسلة المتخصصون - لعبة الثعالب", 150, 95m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "10.5×17", 10, false },
                    { 369, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "وتتابع الرواية محاولة العميد إنقاذ العميل رأفت من براثن الموساد، الذين استغلّوه ككبش فداء لاسترجاع وليد إلى الأراضي المصرية. وبمساعدة \"فهد\"، المعروف بمهاراته الفائقة وقدراته الاستثنائية، والذي تنكر بشخصية طالب لجوء سياسي لدى الموساد، تخترق \"فهد\" الموساد لتحرير العميل المصري. ولأول مرة، لجأت مصر إلى استخدام العنف بتوظيفه كعميل لهذه العملية. دخل في قتال مع الموساد خلال فترة وجوده هناك، وانحاصروا في الداخل، وتنتهي القصة باكتشاف العميد أن مهمة \"فهد\" قد فشلت.", "/images/products/9789778201710.webp", "9789778201710", "سلسلة المتخصصون - عملية الفهد", 132, 85m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "10.5×17", 10, false },
                    { 370, "نبيل فاروق", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور أحداث الرواية حول المناوشات بين أجهزة الاستخبارات المصرية والإسرائيلية خلال الفترة الممتدة بين النكسة (حرب 1967) وحرب أكتوبر (1973). ويصاب أحد الجواسيس الأساسيين، مما يؤدي إلى ولادة فريق \"المتخصصون\"، بقيادة قائد يضم أفراداً مهرة في مجالات متنوعة. هذا القائد، الذي يحمل رتبة عميد، مهووس بلعبة الشطرنج وأسرارها وأهم تحركاتها، فيستخدم هذه الاستراتيجيات لتخطيط عمليات فريقه السرية.\n\nيتخصص كل عضو من أعضاء الفريق في مجال معين مثل القانون، والتجسس، والتخفي، وخلال مهامهم الاستخباراتية يُشار إلى كل متخصص برقم رمزي. وتشمل هذه الجزء من القصة ثلاثة متخصصين وعميل عمليات خاصة يعملون تحت أسماء وجنسيات مختلفة في إسرائيل، يُعرفون بأرقام. ويركز الحبكة على محاولات تحرير المتخصص وليد من قبضة الموساد بجهود باقي المتخصصون. وتنجح العملية في هروب وليد ليجد ملاذًا بين مجموعة من الفلسطينيين، بينما يظل العميد منشغلاً في البحث عن طريقة لنقل كل من وليد ورأفت من إسرائيل.", "/images/products/9789778201703.webp", "9789778201703", "سلسلة المتخصصون - معركة العقول", 184, 100m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "10.5×17", 10, false },
                    { 371, "أميره بهي الدين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يضم هذا الكتاب خمس روايات قصيرة بنكهات متناقضة؛ الانتصار والهزيمة، الأمل والإحباط، العزيمة واليأس.. يتعثر أبطال الروايات الخمس بين حالات وأجواء نفسية وإنسانية متناقضة؛ فنراهم منتصرين مهزومين، فرحين تعساء في نفس اللحظة، لكنهم كانوا وما زالوا أحياء، يعيشون الحياة الصعبة كمن يسيرون على الحبل فوق الهوة البعيدة، وكمن يسيرون حفاة على الزجاج المنثور.. علينا أن نتعلم ونعيش ونواجه، ونتحمل ما سيصادفنا في رحله الحياة، لا نستسلم للهزائم ولا نتباهى بالانتصارات، سنواجه كل المتناقضات والمواقف والمشاعر والتحديات في نفس الوقت وسنعيشها ونتعامل معها، لكن كيف سنخرج من كل هذا، وكيف سنعيش قبله وبعده، أسئلة صعبة تحاول الروايات الخمس أن تعثر لها على إجابات، وربما لم ولن تجد لها إجابات أبدًا..", "/images/products/9789778598520.webp", "9789778598520", "بنكهه المولوتوف والعشق", 396, 290m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 372, "أميره بهي الدين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "لماذا لا نعيش ببساطة؟ سؤال يبدو بسيطًا يطرحه أبطال الروايات الأربع في هذا الكتاب علي أنفسهم وعلينا، فلا يجدون له إجابة ولا نجدها نحن أيضًا.. لماذا لا نحِب ونحَب ونعيش في هناء وفرح لا يستحق حكاية ولا تُكتب عنه رواية؟! لماذا لا تمر الأيام سهلة تبدأ وتنتهي فلا تؤلمنا ولا تسفك دماءنا ولا تلومنا ولا تقهرنا ولا تعصف بنا، فنقضيها ونعيشها كما نحب، وننتهي منها وتنتهي منا بسلام وهدوء؟! من الذي ألقى بنا في عين الإعصار وهو يدور بأقصى بطشه وعنفوانه؟! وما الذي ينتظره منا؟! ولماذا كل هذا والحياة أسهل وأبسط؟ هل الحياة أبسط وأسهل يا إسماعیل؟ ما الذي حدث لك يا ناجي؟ ما الذي اكتشفته يا سليمان بعد كل ما عشته؟ كيف قويت على ما واجهته يا أكرم؟ أسئلة كثيرة حاولت الروايات الأربع الإجابة عنها بمشاعر وأحزان ودموع وغضب وقوة وهشاشة أبطالها الذين عجزوا جميعًا علي العثور علي إجابة السؤال الملح الذي لاحقهم، لماذا لا نعيش ببساطة؟!", "/images/products/9789778598551.webp", "9789778598551", "عندما بلغ سليمان العاشرة", 272, 200m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 373, "أميره بهي الدين", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذا الكتاب خمس روايات يجمع بين عوالمها المختلفة الشديدة التباين وبين أبطالها الغرباء مشقة رحلتهم التي ظنوها رتيبة عادية ستبدأ وتمر وتنتهي دونما نُدوب ولا وجع، لتفاجئهم أيامهم بأثقالها وحزنها ومشقتها وهم يرزحون تحت وطأتها وذكرياتها ونواهيها وقيودها، هل أيٌّ منا حر يعيش ويختار ويفرح ويمضي رحلته طليقًا إلا من أحلامه وأفكاره وأمنياته، أم ستُظهر لنا الأيام دونما توقع ولا انتظار أننا أسرى المفروض الذي لم نختَره وعلينا ترويضه وترويض أيامنا وأنفسنا لنصل إلى بر السلامة كما نظن ونتمنى؟ الاختيار والقدر والمصير، الحرية والمسئولية، الإخفاق والنجاح، كل هذه المعاني وأكثر وأعمق صادفت أبطال الروايات الخمس، وحفرت بنصالها المشحوذة ملامح وشكل رحلاتهم التي سنعيشها معهم.. سليم ابن الحاج أبو حسن ووجعه، باسل وقصيدته التي لم يعثر عليها، يوسف ونبيل ونفيس وعائلتهم الكبيرة، زين ونبيل وعم وصفي ورفقة الهزيمة والنصر، أسامة وحكايته الحزينة مع ملابسه القديمة، كل هذا وأكثر سنعيش معه في الكتاب ورواياته الخمس", "/images/products/9789778598582.webp", "9789778598582", "هلاوس في المخبأ السري", 456, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 374, "إبراهيم الكوني", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بعد أن وصل إلى القائمة المختصرة لجائزة مان بوكر الدولية في عام 2015، نشر الروائي العربي الشهير إبراهيم الكوني رواية بعنوان ناقة الله عبر دار كيان للنشر في عام 2022. تقع أحداث الرواية في ستينيات القرن الماضي حينما كانت الصحراء الكبرى مقسمة بين الدول، وقد سُجن عدد كبير من الطوارق ونُزِعوا من وطنهم، مما مثل بداية نفيهم وتشتيتهم عن جذورهم.\nتتميز رواية إبراهيم الكوني ببطلة من الإبل تُدعى \"تمالالت\" (جاموس بري)، التي تفيض شوقًا ولهفةً عميقة لوطنها، وتصارع كل العقبات في سبيل العودة إلى أرضها. على الرغم من جهود مالكها وحبيبها \"أسيس\"، لا يوجد دواء يخفف من ألم حنينها. تتكشف أحداث الرواية كأنها لحن مؤثر مفعم بالشعر والحنين، مع إثارة تساؤلات فلسفية وروحية عميقة حول معنى الوطن والحرية والعدالة. يبدو أن الكوني أراد أن ترمز ناقة روايته إلى الحب العميق للوطن.", "/images/products/9789778201192.webp", "9789778201192", "ناقة الله", 304, 215m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 375, "فاطمة المهدي", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "بعد الطلاق... تنشأ مشاعر مختلطة—قلق وغضب، فرح وحزن، سعادة وإحباط، وإحساس بالحرية والانطلاق. في لحظة، تختنق بك أنينات قلبك حتى تكاد تخنقك، وفي اللحظة التالية ترى العالم من خلال نظارات وردية براقة. قد يكون قراري صحيحًا... أو خاطئًا... وتظل عالقًا في دورة لا نهاية لها.\nبعد الطلاق، ينبثق بريق أمل في نفق من الظلام، يُعيد إشعال الحياة في قلبك من جديد، ولكن فقط عندما تدرك الدرس بالكامل وتفهم أكثر عن نفسك وعن الحياة مما كنت تعرفه من قبل.\nقد تعتقد بعد الطلاق أن النار لا تُطفأ وأن النهاية وشيكة، لكن نعمة الله تعمل في قلبك دون أن تدري. يبدأ فصل جديد مع ذاتك، حيث ترى العالم بعيون مختلفة؛ وتزين ألوان الطيف حياتك التي كانت مغطاة بالسواد.\nوفي الجانب الآخر من العالم، توجد روح عانت مثلك، تبحث عنك في الزوايا الخفية لكل قصة حب، متلهفة للعثور عليك في كل بيت شعري. وأخيرًا، تلتقيان. تعانقان برفق وتبدآن معًا كتابة حروف قصة حب جديدة لم تتذوق حلاوتها من قبل.\nها هو قلبك بين يديك. فهل أنت مستعد للرحلة؟ انطلق—استمتع، وافرح، وتنفس.", "/images/products/9789778201505.webp", "9789778201505", "تنفس من الطلاق إلى التعافي", 334, 220m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 376, "فاطمة المهدي", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "هذا الكتاب لا يتحدث عن نظريات أكاديمية، ولا يعدك بحياة  مثالية، سيشاركك هذا الكتاب عالمك اليومى مع أبنائك، بدايةً من  شروق الشمس وتزامنًا مع ميعاد المدرسة وواجباتها، مرورًا  .بالمواقف اليومية فى التربية، وحتى موعد الخلود للنوم ستحيا معه بعض المواقف التربوية فى شكل حوار حى فى أسرة  صغيرة، تعيش الحياة مع أبنائها كما تعيشها أنت. يعرض  طريقتك فى التربية التى مللت منها وربما سئمتها، ليعطيك حلولاً  .بسيطة فى شكل حوار شيق.", "/images/products/9789778200010.webp", "9789778200010", "كبسولات تربوية \"تربية عامة\"", 194, 140m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 377, "فاطمة المهدي", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أسئلة تتوارد على أذهان الأبناء وتكون إجابة البعض كالتالى :\nعيب .... عندما تكبر سوف أخبرك أو تنتهى بفتح تحقيق حول من أخبرك بهذا.\nتساؤلات حول الحب والجنس وتكون ردود الأفعال دروسا ومواعظ دون أن نفهم طبيعة المرحلة...\nأحكام وتُهم يلقى بها بعض الأهل على أبنائهم بأنهم قد انحرفوا\nالحديث حول التطورات الجسدية..الرغبات..الجنس الآخر..\nتلك الأشياء الغامضة بالنسبة للأبناء كيف تتصرف حيالها فى ظل عالم منفتح\nكيف تريده أن يفهمك ويفهم العالم من حوله وهو لا يزال يجهل نفسه وطبيعة جسده؟\nإجابات على بعض الأسئلة التى تسبب لك حرجا مع أبنائك .\nسيأخذك هذا الكتاب فى رحلة شيقة نتعلم فيها سويا كيف تتفهم ولدك ..تنصت إليه..تتقبله..\nحتى يتسنى لك تجديد العلاقة معه لتصبح صديقًا ومرجعا له بدلا من أن يتخذ الإنترنت أو صديق السوء مرجعًا له .", "/images/products/9789778200546.webp", "9789778200546", "كبسولات تربوية \"تربية جنسية\"", 252, 180m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 378, "أيمن رجب طاهر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أُمر غالب، مثل كثير من العمال، بالانتقال إلى بورسعيد للعمل لدى البريطانيين، استعدادًا لمعاركهم خلال الحرب العالمية الأولى. كافح غالب لتقرير مصير ابنته الوحيدة؛ فأين سيتركها؟ ومع من؟ وفي النهاية، لم يكن أمامه خيار سوى اصطحابها معه! ولكن ذلك حدث فقط بعد أن تحولت منصورة إلى \"منصور\"، ابن غالب النجار.\n\nتدور أحداث هذه الحكاية في عصر المماليك، وهي قصة رومانسية عن الظلم الاجتماعي والانتقام؛ إذ تهرب شابة مع والدها على متن سفينة، وتلد ولدًا يُدعى \"أنس\". انتزع الأمير المماليك الماكر الصبي من عائلته ورباه كأمير شوارسي، دون أن يعرف أصله، في عالم جديد. هل سيرث الصبي القوة والثروة؟ أم سيثأر لعائلته ولكل المصريين المضطهدين؟", "/images/products/9789778200669.webp", "9789778200669", "الهجانة", 432, 300m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 379, "أيمن رجب طاهر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الرواية من نوع الخيال التاريخي وتدور أحداثها خلال فترة \"المجاعة الكبرى\" في عهد الخليفة الفاطمي المستنصر بالله، مع شخصيات خيالية. تبدأ القصة بخبر عن تراجع مياه النيل، يُبلغ به نساء درب الريحان على يد ناقله \"ريان\"، الذي يأسف على انتشار الجوع والعطش الذي يجتاح البلاد. تتكشف الأحداث تدريجيًا، مصورةً تفاقم المأساة خطوة بخطوة.", "/images/products/9789778200539.webp", "9789778200539", "القحط", 320, 215m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 380, "أيمن رجب طاهر", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ربع المشعلجية، مكان يُفترض وجوده بإحدى الحواري القريبة من ميدان السيدة  زينب، يقطنه العجوز فيض الله مع ابنه تقاوي وحفيدته الشابة منيفة، ويجتر مع رفيق عمره الجد معروف ذكرياتهما أيام حكم الخديو إسماعيل وحفر قناة السويس وحفل افتتاح القناة وأيام الشباب كمجندين بجيش عرابي واشتراكهما في حرب مقاومة الإنجليز وفترة ما بعد الاحتلال الإنجليزي لمصر وتسريحهما من الخدمة وعملهما كمشعلجية لأعمدة النور ثم ذبول تلك المهنة بعد انتشار الكهرباء ومع اقتراب فيض الله من الثمانين إلا أنه يشارك في ثورة الزعيم سعد زعلول 1919م ويرى فيه مقاومة للإنجليز ويتمنى ظهور زعيم في السنوات المقبلة يخلص مصر كلها من حكم الملكية الفاسد والمحتلين الإنجليز المسيطرين على مقدرات الشعوب", "/images/products/9789778202335.webp", "9789778202335", "المشعلجي", 408, 290m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 381, "أيمن رجب طاهر", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فارس، ذلك الشاب الصغير المحب لجمع المعلومات عن علماء ذوي إسهامات علمية غيّرت الحياة على كوكب الأرض للأفضل، يقرأ عن محاولة الإنسان لغزو الفضاء، يقنعه جده بقراءة المزيد من المعلومات عن الفضاء ومحاولة الطيران...\nينهمك فارس في القراءة عن عباس ابن فرناس ويتمنى لو كان قد عاش في عصره، يحلم بذلك؛ كي يرى مبتكرات ابن فرناس، فهل تحقق له ذلك؟!؟", "/images/products/9789778202687.webp", "9789778202687", "على جناح بن فرناس", 144, 90m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "10×17", 10, false },
                    { 382, "مجيب الرحمن مدحت", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في أرض مكة، رأى الفتى المكي محمد رؤيا غريبة.\nرأى العالم من علٍ — الشرق الأوسط وما حوله.\nرأى ومضات، كشرارات خافتة، تومض وتختفي في نقاط متفرقة من أرضنا.\nلكن عينه ثبتت على نقطة واحدة، شعر أن قلبه ينبض على إيقاع ضوئها، الذي لم يخفت.\n\nاقترب منها، مأخوذًا، كأن نداءً سماويًا يدعوه.\nفإذا بها الكعبة — التي يراها كل يوم بين الحجيج والفنادق الشاهقة — لكنها الآن مختلفة. مكسوّة بالرخام، بيضاء، منقوشة بعهود إلهية خُطّت بدم الإنسان.\n\nلاحظ بئرًا لا يعرفه إلا أهل \"ماريا\".\nوقف مذهولًا، والكعبة خلفه، لكنها لم تعد كما يعرفها.\nتحوّلت، كأن ستارًا جديدًا يتكوّن حولها، يحمل ألوان كعبة ماريا.\nوبكى وهو يرى النقوش الدامية تتحوّل، قطرة فقطرة، إلى رجال ونساء وأطفال، يتحرّكون في إيقاع صامت، كرقصة غامضة، أو كحكاية منقوشة على جدار مقبرة فرعونية.\n\nكان كل رجل حرفًا،\nوكل طفل تكوينًا،\nوالمرأة... زينة حزينة تحيط بالكلمات.", "/images/products/9789778200683.webp", "9789778200683", "كسوة جديدة للكعبة", 352, 240m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 383, "عمرو العادلي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة قصصية متنوعة تتخذ من فكرة الكتابة مرسى لها، يحاول الكاتب من خلالها محاورة يوسف إدريس ومناقشة حاسته الإبداعية الاستثنائية، في تجربة اتفق النقاد على أنها فريدة في كتابة القصة القصيرة المعاصرة، فقد تنوعت بين عوالم متعددة قوامها جميعًا الشخصية المصرية، وكيف ترى العالم المحيط بها وكيف تتفاعل معه)", "/images/products/9789778200850.webp", "9789778200850", "حكايات يوسف إدريس", 124, 120m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 384, "ريم مراد", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "منذ سنوات بعيدة يا بنيتي ، بعد عاصفة شديدة ضربت القرية استيقظ أهل القرية علي أجراس عالية أسرع الجميع نحو الصوت، ليجدوا جرسا عملاقا قابعا فوق الرمال بالقرب من الفنار القديم، كبير الحجم ، فظيع الصوت ،  مهيب الشكل ، لم يعلموا من أين جاء و لا متي و لا كيف أو حتى من أحضره ؟؟ حاولوا نقله من مكانه لكن لم يستطيعوا ، لم يستطع أقوي شباب القرية مجتمعين أن يزحزحوه من مكانه ولا حتى شبر واحد .\n‎بقي مكانه هكذا ،أيام و أيام  تناقلت حوله(أم افضل تناقلته) القصص و الإشاعات ، منهم من قال أن عروس البحر كانت تحب إبراهيم ابن الريس عمارة الذي غرق و هو في رحلة صيد و لم تعرف بموته في وقتها و لذا أحضرت هذا الجرس العملاق في المساء و وضعته في مكانه هذا حتى يدق كلما غرق أحدا من الصيادين فتعرف حبيبته بموته و لا تتعذب مثلها ، و منهم من قال أن نرجس الغجرية العجوز التي كانت تعيش مع مجموعة من الغجر عند أطراف القرية و اجتمع أهل القرية و طردوها بعدما عرفوا أنها تمارس السحر الاسود ،فسحرت إحدى شباب القرية لتتعذب كل نساء القرية كلما دق الجرس كما تعذبت هي بطردها من القرية.\n‎و منهم من قال أنه جرس السفينة العملاقة التي غرقت منذ سنوات بعيدة في عرض البحر و أن أمواج البحر تناقلته حتى قذفت به عندهم، اقاويل و قصص عديدة لم تحسم موضوع هذا الجرس الغريب بل زادته غموض ، وما زاد الموضوع غرابة هي ارتباط دقات الجرس بحوادث غرق مراكب الصيد ،فكلما تعرضت أحد مراكب الصيد لحادثة غرق كان الجرس يطلق دقاته تلقائيا حتى أصبح رمزا للموت في هذه القرية الساحلية الصغيرة ، فكلما دق الجرس كانت كل نساء القرية  يخرجن صارخات مولولات يصرخن لا يعلمن علي من ، و لكن حتما علي أحد ، علي زوج إحداهن أو ابنها أو والدها كن يبدأن البكاء حتى قبل أن يعرفن من أو كيف أو متي ؟؟!! كل دقة من دقات الجرس كانت كلدغات كرباك سوداني على جسد كل من له عزيز في البحر، ولأن يا بنيتي الناس يخافون من أي أمر غامض لا يفهمونه ابتعدوا عن الجرس وتجنبوه.....\".", "/images/products/9789778201895.webp", "9789778201895", "إليك انتمي", 246, 220m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 385, "محمد كامل", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يعود أدهم مضطرا بعد خطف غادة من شخص مجهول وغير متوقع للبحث عن الصندوق الذى يبحث عنه الجميع، يعثر عليه ويتفاجأ بمحتوى الصندوق بمساعدة ناديا جارتة التى لا تعرف ما حدث بين أدهم وزوجها القتيل، يكتشف أدهم من هو هذا الشخص بعد أن تتعرف ناديا على صوته وعلى مساعده الذى يقتله أدهم فى شجار ويتخلص من جثته.. تظهر معاناته مع التخلص من آثر الجريمة بسبب هوسة القهرى\nوينتهى الأمر بلقاء يجمع الكل فى مكان مهجور تحاول آية أن تقتل أدهم لكن ناديا تنقذة وتتخلص من آية، حسن يكاد يصرع أدهم فى شجار لكن ناديا تعاود نجدته باطلاق الرصاص على حسن الذى يفر هاربا.\nيقرروا الإحتفاظ بالصندوق رغم خوف أدهم مما يمكن أن يحدث لاحقا بسببه", "/images/products/9789778202755.webp", "9789778202755", "بعد النهاية (الجزء الثاني)", 316, 190m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 386, "تامر احمد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "(تشركا تروفا) أو من يبحث يجد هي رواية واقعية مبنية على أحداث حقيقية من واقع ملفات إحدى\nالمنظمات الدولية العاملة في مجال البحث والتقصي.\nبطل الرواية &quot;أشرف عبد الفتاح&quot; مسئول التقصّي في إحدى المنظمات الدولية، عمله هو البحث عن\nالمفقودين بسبب الحروب والنزاعات المسلحة وتجميع شتات العائلات التي تفرقت لهذه الأسباب أو\nلغيرها. تأخذنا الرواية المأخوذة عن أحداث حقيقية في ثلاث مغامرات يحقق فيها اشرف في قضايا\nاختفاء اشخاص مفقودين وتلقي الضوء على طريقة عمل المنظمات الإنسانية في هذا المجال. تظهر\nالرواية كيف يجمع أشرف المعلومات والأدلة ويربط بينها ببراعة كي يرى الصورة كاملة.\nأحداث الرواية متلاحقة مثيرة تفوق الخيال رغم أنها حقيقية مئة بالمئة، حيث تدور أحداث القضية\nالأولى في (موريتانيا) في رحلة بحث بطلها الطفل إدريسو الذي تم العثور عليه وحيدا في مدينة\n(باسيكونو) أقصى جنوب غرب (موريتانيا) ، بينما تدور أحداث القضية الثانية بين (البوسنة) و(كرواتيا)\nو(سويسرا) حيث يبحث أشرف مع الشابة إيمينا عن والدها الذي فقد أثره عقب هروبه من أحد معتقلات\nالصرب، أما القضية الثالثة فتدور أحداثها بالأساس في (ليبيا) حيث يقوم أشرف بالبحث عن أربعة\nأشخاص مصريين منهم طفل صغير دخلوا الحدود الليبية في رحلة هجرة غير شرعية ليلاقوا الأهوال\nفي الصحراء الليبية ويفقد أثرهم تماما.", "/images/products/9789778202748.webp", "9789778202748", "تشركا تروڤا", 464, 320m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 387, "حسن الحلبي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تتحدث رواية (لا ربيع في هذه المدينة) عن شخص اسمه (قاسم)، يعيش في مدينة تعاني من صراعات الحرب، حيث يجد نفسه في المستشفى وقد فقد ساقاً كاملة بسبب صاروخ استهدف المنطقة التي يسكن فيها، ليجد أنه مضطر لتلقي العلاج في المستشفى، حيث يجد نفسه في غرفة يتغير زملاؤه فيها كل يوم، لتتغير القصص والحكايات والمواقف الصادمة، التي تتحدث كلها عن الحرب، وحتى الممرضات يتم قتلهن كل يوم بواسطة أحد القناصين المختبئين أمام المستشفى.", "/images/products/9789778201864.webp", "9789778201864", "لا ربيع في هذة المدينة", 128, 120m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 388, "شريف ثابت", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تدور احداثها في المستقبل القريب و محاولة الثورة الثانية علي شركة ايجى نيرجى فهل ستنجح الثورة ام ستفشل كسابقتها", "/images/products/9789776376861.webp", "9789776376861", "عالم أفضل - القيامة", 294, 215m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 389, "شريف ثابت", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "فى مستقبل قريب مظلم، تنضب موارد الطاقة التقليدية من نفط وغاز طبيعى وخلافه، وتعجز الطاقة المتجددة عن سد الحاجة العالمية المتزايدة للطاقة.. تصبح الكرة فى ملعب إيجى- نيرجى.. الشركة العملاقة، عابرة القارات، المتخصصة فى استخلاص الطاقة النفسية من الأجساد البشرية (عن طريق تعذيبها حتى الموت) ثم تحويلها لطاقة كهربية..\n\nبعد ما يقرب من ربع القرن من الاستقرار والسيطرة على سوق الطاقة.. تنفجر الأحداث مجدداً مع هروب أحد ضحايا الشركة من داخل ماكينات التعذيب، وقد اكتسب قدرات غير طبيعية جعلت منه سلاحاً رهيباً، تصارع الشركة من جهة، وخصومها من الجهة الأخرى، للوصول إليه أولاً..\n\nمن أجل عالم أفضل، يتقاتل الجميع لفرض قواعده، كلُ وفقاً لرؤيته.. تراق الدماء بلا حساب، وتشتعل الحرب من جديد..", "/images/products/9789776376687.webp", "9789776376687", "عالم افضل - الميلاد", 290, 215m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 390, "أحمد الزناتي", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "صحفيّ شاب يتعثّر في كتابة روايته الأولى، فيدوّن شذرات في دفتره. في شاليه على البحر ينام إلى جوار حبيبته، وحينما تنهض الحبيبة، تعثر على الدفتر مفتوحًا، الصفحات اليُمنى مسوّدة، واليُسرى فارغة. تجلس إلى مكتبه، وتعيد كتابة الحكاية، أو بالأحرى ملأ ثغراث الحكاية، لكنها تجهل ما ينتظرها.\nرواية منسوجة بخيوط الحُلم والحقيقة عن صدُفات الحياة، وعن القدر، وعن استحالة معرفة أنفسنا ولا معرفة الآخرين معرفة يقينية.", "/images/products/9789778200522.webp", "9789778200522", "لعبة الخيول الخشبية", 192, 140m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 391, "سلمى الغزاوى", 4, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "آن أوان ارتمائي في أحضان الموت وفيه خلاصي، سأذهب لأقف وجها لوجه مع الحاصد الذي أخلفت موعدي معه، ولهذا أبى أن يقطف روحي، سأتخطى حاجز الردى، لعل أحدهم يطلق عليّ رصاصة الرحمة التي أجّلتها الحياة لمدة طويلة، سأتركهم يطلقون سراح روحي المعذبة لأنه لم تكن لدي الشجاعة الكافية لأنهيها بمجرد موت عائلتي، عساني حينها أنجح في عبور نهر الموت، والصعود على متن أحد قواربه بأقل الأوجاع الممكنة، ليوصلني حارس الموتى إلى الأبدية.", "/images/products/9789778200003.webp", "9789778200003", "تلاندسيا", 156, 120m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 392, "شريف شعبان", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "For thousands of years and to this day, there have been numerous myths and misconceptions about ancient Egypt in the minds of many around the world. Perhaps it is because of the nature of the ancient Egyptians to keep the secrets of their civilization within the minds of their priests, like the secrets of the ancient Egyptian language and  hieroglyphic writing, magical secrets, miracles of architecture,  astronomy, and other knowledge that  other nations  could not understand, and turned into mysteries.  This book comes as a serious and sincere attempt to reveal  falsehoods and refute the myths surrounding ancient Egyptian  civilization, which unfortunately turned into facts in mind of the public and some specialists both inside and outside Egypt. So, let me take you through an interesting journey to discover the secrets of Ancient Egypt and to reveal its mysteries and myths.", "/images/products/9789778201314.webp", "9789778201314", "secrets of the pharoahs", 164, 130m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 393, "بيشوي القمص", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مشروعات تشاوشيسكو المكلفة وحرية الاقتراض من الغرب أغرقت رومانيا في الديون إلى حد اضطرت معه الحكومة إلى تصدير بعض السلع على حساب الاستهلاك المحلي، وتدهور الاقتصاد الروماني إلى حد غير مسبوق، وانهارت مستويات المعيشة للغالبية العظمى من الرومانيين، حتى وصفت رومانيا في ذلك الوقت بإثيوبيا أوربا. ومع بداية الثمانينيات، أصبح سداد هذا الدين عبئًا كبيرًا على مالية الدولة، فقرر تشاوشيسكو سداد ديون رومانيا بالكامل، ونظم استفتاء على إجراء تعديل دستوري يمنع رومانيا من تلقي قروض من الخارج في المستقبل، وبناء على هذا القرار، جرى توجيه معظم الإنتاج الصناعي والزراعي للبلاد من أجل سداد الدين، وكانت نتيجة هذه الإجراءات كارثية على الأغلبية الساحقة من الشعب، حيث تم تعميم نظام الحصص من السلع الغذائية في جميع أنحاء البلاد باستثناء العاصمة، وجرى تقليص هذه الحصص على نحو مستمر، وتراجع استهلاك الطاقة بصورة مروعة، وتوقفت أنظمة التدفئة المركزية، وحتى التلفزيون الرسمي قلصت قنواته لتصبح قناة واحدة تبث لمدة ساعتين فقط يوميا، أما الكهرباء فكان يتم قطعها لساعات طويلة وخاصة في الليل من أجل التوفير، وبلغ الفقر وضيق المعيشة مستويات غير مسبوقة، وتم وقف الاستيراد بصورة شبه كاملة، باستثناء استيراد السلع الفاخرة لتشاوشيسكو والزمرة المحيطة به، حتي تم سداد ديون رومانيا كاملة في صيف 1989.", "/images/products/9789778200430.webp", "9789778200430", "لا احد يتعلم من التاريخ 2 - قيصر جديد", 212, 150m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 394, "بيشوي القمص", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يقول الفيلسوف الألماني الشهير فريدرش هيجل \"نتعلم من التاريخ، أن أحداً لم يتعلم من التاريخ\"..\n على غرار الجزء الأول والثاني، يتناول الجزء الثالث من سلسلة \"لا أحد يتعلم من التاريخ\" صراع العروش في كل من سوريا والعراق، منذ اللحظة الأولى لأنطلاق الثورة العربية الكبرى من مكة على يد الشريف حسين بن علي الهاشمي، مروراً بتأسيس الممالك الأربعة في نجد والأردن وسوريا والعراق، ولعبة الكراسي الموسيقية بين عسكر سوريا حتى قيام الجمهورية العربية المتحدة وسقوطها، وصولاً لحكم الاسد وأبناءه، كما يتناول الكتاب تاريخ الملكية في العراق، والمطامع التاريخية في دولة الكويت، ولعبة الكراسي الموسيقية بين عسكر العراق وصولاً لحكم صدام حسين.", "/images/products/9789778201239.webp", "9789778201239", "لا أحد يتعلم من التاريخ 3 - صراع العروش بين سوريا والعراق", 248, 180m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 395, "سالي العقاد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "الكتاب يروي قصصًا حقيقية من ساحات العمل، حيث يسود المدير المتسلط أو الغائب عقليًا، وهو لا يسعى لتشويه أحد بقدر ما يسعى لتحويل هؤلاء إلى أمثلة... لا يُحتذى بها!\n\nقد تتساءل: \"وماذا سأستفيد؟\"\n\nالإجابة: الكثير!\nتشير الدراسات إلى أن 75% من الموظفين يَرَون أن مديرهم هو أسوأ ما في العمل، وأن واحدًا من كل اثنين يترك وظيفته بسبب الإدارة السيئة. والأسوأ من ذلك، أن الإدارة الرديئة لا تفقد الشركات موظفيها فحسب، بل عملاءها وإيراداتها أيضًا.\n\nفي المقابل، تُظهر أبحاث DDI وMcKinsey أن المؤسسات ذات القيادة الفعّالة تحقق أداءً وإيرادات أعلى بنسبة تصل إلى 37%.\n\nالقيادة السيئة سمّ بطيء، تنخر في ثقافة المؤسسة، وتخلق بيئة سامة تخنق الإبداع وتُضعف الإنتاجية.\nوقد أظهرت دراسة لـHBR أن 91% من الموظفين يرون أن ضعف التواصل الإداري يقتل الروح المعنوية.\n\nلكن هذه \"اللعنة\" قد تحمل دروسًا ذهبية، لا تُدرّس في كتب الإدارة التقليدية. هذا الكتاب دعوة للتأمل في تلك اللحظات العبثية التي مررنا بها مع مدراء فقدوا البوصلة.\n\nفي الختام:\n\nاحمل فنجانك مجددًا، خفف من جديتك قليلًا، وانضم إلينا في هذه الرحلة الساخرة – لعلنا نضحك، ونتعلم، ونكفّ عن تكرار الأخطاء نفسها.\n\nوخلاصة القول: قصص لم تُروَ من كواليس الإدارة الفاشلة، ودروس حقيقية من ساحات العمل، نقد ساخر لثقافة قيادية متعفنة، ورسالة إلى كل من اعتقد أن القيادة مجرد منصب، لا مسؤولية.", "/images/products/9789778598599.webp", "9789778598599", "سجلات الليدر شيت", 170, 160m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 396, "إبراهيم عبد المجيد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "النسيان هو أجمل النعم الالهية. فالجهل مثلا يمكن تعويضه بالعلم والفقر يمكن تعويضه بالعمل والكسب، والفقد يمكن تعويضه بالصبر، لكن الإنسان حتى الآن لم يستطع أن يتغلب على النسيان. إنه يحاول وهناك عشرات العقاقير التي تساعد على التذكر لكن يظل النسيان قائما مهما فعلت ومهما قاومت... وفرويد عالم النفس الشهير قدم تفسيرًا صائبا للنسيان: أن ما تنساه هو ما ليس لك رغبة فيه؛ فاللاشعور يساعدك ويطرد ما لا تحبه من الذاكرة لتتوازن شخصيتك وفرويد هنا لا يتحدث عن النسيان الذي قد يحدث لأسباب فيزيقية تتعلق مثلا بتقدم العمر أو حوادث تصيب المخ بفقدان الذاكرة، فرويد هنا يتحدث عن الشخصية السوية.", "/images/products/9789778202311.webp", "9789778202311", "حاولت ان انظر حولى وامامى", 322, 245m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 397, "يسرية عبد العزيز", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يقدم الكتاب دراسة معمقة عن تساؤلات الوجود ونشأة الحياة كما انعكست في أساطير الحضارات القديمة. يتناول مفهوم البداية في العقل البدائي من خلال نماذج متعددة لأساطير الخلق في مصر القديمة، بلاد الرافدين، والصين، وغيرها. يبرز أهمية الماء كجوهر الحياة ومصدر الكون في أغلب الأساطير، ويستعرض قصصًا مثل البيضة الكونية عند الإغريق، وفلسفة الأشمونين التي تمحورت حول المياه الأزلية.\n\nالكتاب يربط بين تطور الفكر الديني والفلسفي وبين الحاجة لتفسير الظواهر الطبيعية، مثل ظهور النور، والسماء، والأرض، ويبحث في أثر هذا الفكر على تنظيم المجتمعات القديمة وصياغة مفاهيم الأخلاق والدين. كذلك، يناقش النصوص الجنائزية المصرية مثل نصوص التوابيت ومتوني الأهرام، التي تقدم تصورات تفصيلية عن الخلق والحياة بعد الموت.\n\nفي النهاية، الكتاب ليس فقط دراسة عن الماضي، بل هو محاولة لفهم كيف كان الإنسان البدائي يسعى لملء فراغات الوجود بأسئلة لم تتوقف حتى اليوم. يُبرز أهمية الفلسفة والأسطورة في بناء الثقافة الإنسانية، مما يجعله إضافة فكرية مهمة.", "/images/products/9789778202793.webp", "9789778202793", "لغز الوجود والعقل البدائي", 166, 180m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 398, "طاهر المعتز بالله", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تجتمع في هذا الكتاب حكايةُ أكبر إبادة عرقية في التاريخ وقصة أعظم داعية إسلامي في أمريكا وحكاية أعظم شخصية رياضية في القرن العشرين، وعندما تجتمع كل هذه الأشياء معًا فاعلم أنك أمام وجبة دسمة من المعرفة، ستغيِّر منظوركَ للكثير من الأمور.\nفكيف اكتشف «كريستوفر كولومبوس» أمريكا؟ وأي ثمن دفعه السكان الأصليون؟\nوكيف تحوَّل «مالكوم إكس» من حياة الإجرام والضياع وصار خطيبًا مفوَّهًا يحرِّك الجموع بكلماته؟\nوما السر الذي جعل «محمد علي كلاي» الملاكم الأعظم في التاريخ؟\nوما الشَّبه بين ما حدث في أمريكا من إبادة عرقية، وما يقوم به الكيان الصهيوني في فلسطين؟\nوكيف تحوَّل إخوة الأمس لأعداء اليوم؟ ومَن الذي اغتال «مالكوم إكس»؟\nوكيف شاركت عنصرية الرجل الأبيض وأطماعه في جميع حكايات هذا الكتاب؟\n\nمن لا يعرف التاريخ فمحكوم عليه بتكراره، وصدقني لن ترغب في تكرار الكثير من الأشياء في هذه الحكايات.", "/images/products/9789778202434.webp", "9789778202434", "سلسلة الدحيحة - الآخوة الإعداء", 316, 220m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 399, "طاهر المعتز بالله", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يقول المثل: فاقد الشيء لا يعطيه، ولكنه أحيانًا يعطيه بغزارة. ديانا افتقدت الحب في حياتِها فمنحته لكل مَن حولها. كانت كالشمس مصدرًا للضوء والدفء، فدار الرجال في فلكِها منجذبين إلى نورِها، ولكن مَن اقترب منها احترق بنارِها؛ فمن قتل ديانا؟ وكيف قُتِلت؟ كيف عاشت؟ وكيف أحبَّت؟ كيف انتصرت؟ وكيف هُزِمت؟ والأهم من كل ذلك، كيف استطاعت الفوز بحب الملايين في حياتها إلى درجة جعلتها من أشهر شخصيات العالم وأكثرهم شعبية رغم مرور أكثر من 25 عامًا على وفاتها؟", "/images/products/9789778201543.webp", "9789778201543", "سلسلة الدحيحة - ديانا", 312, 200m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 400, "طاهر المعتز بالله", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "دراسة اينشتاين تساعد علي فهم ما هي جذور العبقرية. الكتاب مهم للاهالي لمعرفة كيفية التعامل مع اطفالهم بشكل يسمح بتنمية اهتماماتهم بدلا من كبتها او محاولة تغييرها. اينشتاين كان طفل عادي بل اقل من العادي، يعاني من مشاكل في النطق بشكل جعل اهله يظنون ان امكانياته العقلية محدودة. ومع ذلك دعموه، وتحملوا شخصيته المستقلة حتي اصبح ما هو عليه. وفي نفس الوقت الكتاب مهم للطلاب لمعرفة تاريخ العلوم التي يدرسون معادلاتها دون معرفة ظروفها التاريخية. معرفتهم لسير العلماء تجعل منهم بشر مثلهم، وتحول العلم لمادة حية أكثر امتاعا. الكتاب يحمل فصل اضافي عن انفجار مفاعل تشيرنوبل لانه يربط بين حادثين غاية في الاهمية، الاول هو اختراع القنبلة الذرية، والثاني هو الحرب الروسية الاوكرانية، حدثان مرتبطان بشكل حثيث رغم بعد ازمنتهما، وكلاهما لم ليحدثا لولا شخص واحد فقط، وهو البرت اينشتاين.", "/images/products/9789778201659.webp", "9789778201659", "سلسلة الدحيحة - اينشتاين", 272, 215m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 401, "نهى محمود", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "\"مجموعة قصصية في إحدى عشرة قصة، عن أحلام زوجات\nصغيرات بحياة سعيدة... وونس وحب، وتأملات نساء صادف أن مر العمر دون أن يقابلهم الحظ والحب...\nورجال يبحثون عن المجد والمال والسعادة... مجموعة بها خيالات عن مستقبل ربما يجيء، وأشباح قصص حب رغم غرقها في دوامات الماضي إلا أنها تطيل أحيانا من هناك لتربك الحكايات\nالجديدة، وتعم فوضى المشاعر بين ما مر وما جاء بين البشر الذين غادروا والذين طال انتظارهم ولم يمروا أبدا من هنا... طرق طويلة وممتدة يحتاج الجميع المضي فيها ربما يجدون سبيلا للوصول....\"", "/images/products/9789778201857.webp", "9789778201857", "السير في طرق هادئة ممتدة وبعيدة", 136, 120m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 402, "عمرو العادلي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة مكونة من 20 قصة، تتراوح بين الواقعى والفانتازى، وفيهارؤية الكاتب عن فن القصة القصيرة، ليس بشكل تنظيرى لكن بشكل عملى\".", "/images/products/9789778200126.webp", "9789778200126", "و", 154, 120m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 403, "فاطمة الزهراء الرياض", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "مجموعة من القصص والنصوص الواقعية، التي تلتقط مواقف وأحداثًا مهملةً تمر أمام أعيننا جميعًا كل يوم حتى لم نعد نراها أو نلتفت إليها، وتتوقف عندها وتغوص في شخوصها لتتأملهم لحظة، وتريك كم هي مدهشة، وكم هو مدهش أننا فقدنا قدرتنا على الاندهاش والتأمل والتعمق إلى هذا الحد.\"", "/images/products/9789776376342.webp", "9789776376342", "لقاء يفك ازرار السماء", 126, 120m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 404, "تسنيم فهيد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تمسّد «أمي» الحائط الذي وضعتني فيه قبل سنوات بعيدة. تطلب مني أن أتحول من «حارث» إلى «حارس». تُعلِّق عينيها بالحائط والسقف. تناجي الرب وتتشفع بعدد من فقدت طيلة سنوات كثيرة. تنظر للحائط بغضب، تطلب مني أن أفعل شيئًا وأن أمنع ملك الموت من أن يجوس الغرفة ويقترب من أُختي. أسمع بكاءها ونجواها وأتطلع معها عاجزًا- نحو السقف.", "/images/products/9789776376656.webp", "9789776376656", "أم الولى", 146, 120m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 405, "تامر أحمد", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كل موظف لديه أداة تعذيب مفضلة لسلخ المواطن المصري وتعجيزه .. منها: فوت علينا بكرة .. السيستيم واقع .. الختم مش واضح .. الخزنة قفلت .. ولكن أشد هذه الوسائل عنفا وتأثيرا هي \" عند مدام عفاف \" التي تقف كالسد العالي أو كمحاربي السومو أمام من تسول له نفسه من المواطنين التقدم بأي طلب .. في هذا الكتاب ثلاث قصص ساخرة لمواطنين تم تعذيبهم بالروتين والبيروقراطية ومدام عفاف .. وفي حين تبدو القصص خيالية الا انها - ويا للعجب - مأخوذة عن قصص حقيقية مائة بالمائة. في نهاية هذا الكتاب مفاجئة لقراء د. أحمد خالد توفيق .. حيث يطل علينا رفعت اسماعيل وماجي في قصة ساخرة بالكامل ( اسطورة الفتوة ) كيف يتحول رفعت اسماعيل من طبيب واستاذ جامعي الي (فتوة) هذا ما يتبين من الأحداث .. وقد نشرت هذه القصة بناء على موافقة سابقة من د. احمد خالد توفيق رحمه الله", "/images/products/9789778200713.webp", "9789778200713", "عند مدام عفاف", 160, 120m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false },
                    { 406, "أمل دُنقل (إعداد أنس دنقل)", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتاب قصائد أولى للشاعر أمل دنقل هو مجموعة من القصائد التي تميزت بعمقها العاطفي والنقدي والاجتماعي، وكتبها الشاعر في مقتبل حياته، ما يظهر فيها بساطة التعبير وأصالة الأحاسيس. يتناول الكتاب مواضيع متعددة من بينها الحب، الألم الإنساني، النقد السياسي والاجتماعي، والصراع الداخلي. ومن أبرز قصائده \"العيون الخضر\"، \"أين المسيح؟\"، \"اعتراف\"، و\"أوجيني\"، والتي تجمع بين الجمالية اللغوية والعمق الفكري.", "/images/products/9789778202809.webp", "9789778202809", "قصائد أولي (أمل دُنقل)", 160, 130m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×20", 10, false }
                });
        }

